/* ===== p2 · Writer W11: deeper arcs for the main supporting cast =====
 Arcs (all STORY events, prefix p2_):
  A Rui comes to Texas      W32–34   p2_rui_call / p2_rui_arrive / p2_rui_talk / p2_rui_leave
  B Travis's other side     W18, 30, 35, 41   p2_travis1–4 (W41 forks on S.flags.travisDeal)
  C Earl sells the saloon   W23, 38, 43, 47   p2_earl1–4 (+ EXTRA_LOCS 'p2_saloon' back office if you own a share)
  D Albertina turns eighty  W16, 26, 44, 46   p2_alb1–4
  E Tommy & Little Dale     W14, 27, 41, 45   p2_kids1–4
  F Drought at the Reyes ranch W9, 21, 40     p2_ranch1–3
 Public flags (read them anywhere):
  S.flags.p2_calls        number   times you used "Call home" (counted by a thin wrapper around callHome)
  S.flags.p2_rui          'coming'|'later'      whether Rui visited in W33–34
  S.flags.p2_viola       'kyle'|'you'|'paper'|'kept'  her husband's twelve-string guitar (W46); kyle/you = it plays in the parade
  S.flags.p2_ruiFuture    'next'|'home'|'partner'|'open'  what you told him about staying
  S.flags.p2_ruiKnows     1        Rui knows the truth about the wreck
  S.flags.p2_travis       'turned'|'bad'|'humbled'|'bitter'  Travis after chapter 4 (turned/bad on the deal path)
  S.flags.p2_tv           number   Travis's "other side" points (0–4)
  S.flags.p2_saloon       'bought'|'half'|'coop'|'jolene'|'travis'  who owns the Lone Star after W43
  S.flags.p2_alb80        'lisbon'|'austin'|'kyle'|'net'  how Albertina's song was found (birthday W44)
  S.flags.p2_tommy        'college'|'stay'
  S.flags.p2_ld           'blessed'|'alone'     Little Dale leaves for Austin with/without his father's blessing
  S.flags.p2_beto         'held'|'option'       Beto kept the south pasture / signed an option with the broker
*/
const P2={
 at:(w,d,s,span)=>()=>!S.where&&S.week>=w&&S.week<=w+(span==null?1:span)&&(S.week>w||S.day>d||(S.day===d&&S.slot>=s)),
 contact:()=>(S.flags.p2_calls||0)+Math.floor((+S.flags.sentMoney||0)/200)+(S.flags.toldFamilyLetters?2:0),
 partner(){if(S.settled&&NPCS[S.settled])return S.settled;const c=Object.keys(NPCS).filter(k=>NPCS[k].romance&&rel(k).met&&rel(k).like>=5).sort((a,b)=>rel(b).like-rel(a).like);return c[0]||null},
 tv(n){S.flags.p2_tv=Math.max(0,(S.flags.p2_tv||0)+n)},
 letters:n=>()=>S.letters>=n||NEED(t(`若泽的信 ${n} 封`,`${n} of José's letters`,`${n} cartas do José`)),
 fishPerk(){grantPerk('fish',0.8,['席尔瓦家的孙子','the Silva grandson','o neto do senhor Silva'])},
 beefPerk(){grantPerk('beef',0.8,['雷耶斯牧场','Reyes Ranch','Rancho Reyes'])},
 M:{rui:t(`鲁伊`,`Rui`,`Rui`),travis:t(`特拉维斯`,`Travis`,`Travis`),earl:t(`厄尔`,`Earl`,`Earl`),alb:t(`阿尔贝蒂娜太太`,`Dona Albertina`,`Dona Albertina`),kids:t(`汤米和小戴尔`,`Tommy and Little Dale`,`O Tommy e o Dale Júnior`),ranch:t(`雷耶斯牧场`,`Reyes Ranch`,`Rancho Reyes`)}
};
// count calls home so Rui's visit can depend on them
const p2_callHome0=callHome;callHome=function(){S.flags.p2_calls=(S.flags.p2_calls||0)+1;return p2_callHome0()};

/* ---------- the saloon back office (only if you own a share) ---------- */
EXTRA_LOCS.push({id:'p2_saloon',n:t(`孤星酒吧的账房`,`The Lone Star back office`,`O escritório do Lone Star`),open:()=>['bought','half','coop'].includes(S.flags.p2_saloon),acts:[
 {id:'p2_till',n:t(`对一周的账`,`Do the week's books`,`Fazer as contas da semana`),cost:1,req:()=>S.flags.p2_tillWk===S.week?t(`这周的账已经对过了`,`This week's books are done`,`As contas desta semana já estão feitas`):true,
  run:()=>{S.flags.p2_tillWk=S.week;const share={bought:1,half:0.5,coop:0.25}[S.flags.p2_saloon]||0,g=Math.round(R(260,420)*share);S.cash+=g;
   return say(t(`账房`,`Back office`,`Escritório`),[t(`点唱机在门外响着。你数完一周的零钱，厄尔从吧台尽头喊：“别忘了给冰柜除霜。”`,`The jukebox plays outside the door. You count the week's cash while Earl hollers from the end of the bar: "Don't forget to defrost the cooler."`,`A jukebox toca do outro lado da porta. Contas o dinheiro da semana enquanto o Earl grita do fundo do balcão: «Não te esqueças de descongelar a arca.»`)],t(`你的份额 +$${g}`,`Your share +$${g}`,`A tua parte +$${g}`))}}]});

STORY.push(
/* =============== F · drought at the Reyes ranch =============== */
{id:'p2_ranch1',when:()=>!!S.flags.ranch&&P2.at(9,4,1,2)(),run:()=>({title:t(`四十一天没下雨`,`Forty-one days without rain`,`Quarenta e um dias sem chover`),meta:P2.M.ranch,text:[
 t(`四十一天没下雨。牧场的蓄水池裂成一块块龟壳，贝托每天夜里开着水罐车去河边拉水，一趟两个小时。`,`Forty-one days without rain. The stock tank has cracked into turtle-shell plates, and every night Beto drives the water truck to the river and back, two hours a trip.`,`Quarenta e um dias sem chover. O bebedouro estalou em placas de carapaça de tartaruga, e todas as noites o Beto vai com o camião-cisterna ao rio e volta, duas horas por viagem.`),
 t(`露西娅在算账：“再旱两个星期，就得把三十头母牛拉去拍卖，半价。”南边那口井就在栅栏外，水满满的，盖着铁板，铁板上用红漆写着“不准喝”。`,`Lucía is doing sums. "Two more dry weeks and thirty cows go to auction at half price." The south well sits just past the fence, full to the brim, under an iron plate painted in red: DON'T DRINK.`,`A Lucía faz contas. «Mais duas semanas secas e trinta vacas vão a leilão a metade do preço.» O poço do sul está logo depois da cerca, cheio até cima, tapado com uma chapa de ferro pintada a vermelho: NÃO BEBER.`)],choices:[
 {t:t(`跟着拉一整夜的水`,`Haul water with them all night`,`Carregar água com eles a noite toda`),fx:()=>{stat('tex',3);addTrust('beto',1);S.energy=Math.max(0,S.energy-2)},next:()=>say(t(`凌晨四点`,`Four a.m.`,`Quatro da manhã`),t(`最后一罐水倒进池子时天快亮了。贝托递给你一瓶冰啤酒，还是什么都没说。`,`The last load goes into the tank just before dawn. Beto hands you a cold beer and, as usual, says nothing.`,`A última carga entra no bebedouro pouco antes do amanhecer. O Beto dá-te uma cerveja fresca e, como sempre, não diz nada.`),t(`德州味 +3 · 贝托信任 +1 · 精力 −2`,`Texanness +3 · Beto's trust +1 · Energy −2`,`Texanidade +3 · Confiança do Beto +1 · Energia −2`))},
 {t:t(`借给他们 $400 买干草`,`Lend them $400 for hay`,`Emprestar-lhes $400 para feno`),req:MONEY(400),fx:()=>{S.cash-=400;S.flags.p2_betoLoan=400;addTrust('beto',1);addTrust('lucia',1)},next:()=>say(t(`借条`,`The IOU`,`O papel da dívida`),t(`贝托把钱推回来两次。第三次，露西娅替他收下，写了一张借条。“他从来不借钱，”她说，“所以借的每一分都会还。”`,`Beto pushes the money back twice. The third time Lucía takes it for him and writes an IOU. "He never borrows," she says. "So every cent he does borrow comes back."`,`O Beto devolve o dinheiro duas vezes. À terceira, a Lucía aceita-o por ele e escreve um papel. «Ele nunca pede emprestado», diz. «Por isso, cada cêntimo que pede volta.»`))},
 {t:t(`[手艺 35] 给工人们做一锅阿连特茹冷汤`,`[Craft 35] Make the hands a pot of Alentejo cold soup`,`[Ofício 35] Fazer aos trabalhadores um gaspacho alentejano`),req:()=>S.stats.oficio>=35||NEED(t(`手艺 35`,`Craft 35`,`Ofício 35`)),fx:()=>{addTrust('lucia',1);stat('oficio',1);S.lusoThisWeek=true},next:()=>say(t(`冷汤`,`Cold soup`,`Gaspacho`),t(`番茄、黄瓜、大蒜、隔夜面包。玛丽索尔尝了一口：“这是汤还是沙拉？”然后喝了两碗。`,`Tomato, cucumber, garlic, yesterday's bread. Marisol tastes it. "Is this soup or salad?" Then she has two bowls.`,`Tomate, pepino, alho, pão de ontem. A Marisol prova. «Isto é sopa ou salada?» Depois come duas tigelas.`))},
 {t:t(`问那口井为什么封着`,`Ask why the well is sealed`,`Perguntar porque está o poço tapado`),fx:()=>{S.flags.p2_wellAsk=1},next:()=>say(t(`南井`,`The south well`,`O poço do sul`),t(`贝托把草根吐掉：“1998 年，若泽和我一起封的。有些水，牛喝了会掉毛，人喝了会闭嘴。”他转身去发动水罐车。`,`Beto spits out his grass stem. "José and I sealed it together in '98. Some water makes cattle lose their hair. Makes men keep their mouths shut." He turns to start the water truck.`,`O Beto cospe a palha. «Fui eu e o José que o tapámos, em 98. Há águas que fazem cair o pelo às vacas. E que fazem os homens calar-se.» Vira-se para ligar o camião.`))}]})},

/* =============== E · Tommy & Little Dale (1) =============== */
{id:'p2_kids1',when:P2.at(14,5,2),run:()=>({title:t(`周五夜灯`,`Friday night lights`,`Luzes de sexta à noite`),meta:P2.M.kids,text:[
 t(`圣鲁伊斯赢了。汤米在最后一分钟接住一记长传，跑了六十码，现在一身草皮白灰，坐在你店里吃第三个猪排包。`,`San Luís won. Tommy caught a long pass in the last minute and ran sixty yards; now, still chalked white from the field, he's at your counter on his third pork sandwich.`,`San Luís ganhou. O Tommy apanhou um passe longo no último minuto e correu sessenta jardas; agora, ainda branco da cal do campo, está ao teu balcão na terceira bifana.`),
 t(`“俄克拉何马一所小大学的教练来看了。半奖。”他说得很快，“我妈上夜班，我妹九岁。”好像说快一点，就不算个问题。`,`"A coach from a little college in Oklahoma came to watch. Half scholarship." He says it fast. "Mom works nights. My sister's nine." As if saying it fast keeps it from being a problem.`,`«Veio um treinador de uma universidade pequena de Oklahoma ver o jogo. Meia bolsa.» Di-lo depressa. «A minha mãe trabalha de noite. A minha irmã tem nove anos.» Como se, dito depressa, não fosse um problema.`),
 t(`小戴尔推过来一本速写本：你的门面、烤架、水塔；最后一页，是店后空地上一座他想象出来的房子。“我想去奥斯汀读建筑，”他小声说，“我爸以为我要去韦科读贝勒，然后进神学院。”`,`Little Dale slides over a sketchbook: your shopfront, the grill, the water tower; on the last page, a house he's imagined on the empty lot out back. "I want to study architecture in Austin," he says quietly. "Dad thinks I'm going to Baylor in Waco, then seminary."`,`O Dale Júnior empurra um caderno de esboços: a tua fachada, a grelha, a torre da água; na última página, uma casa que imaginou no terreno vazio das traseiras. «Quero estudar arquitetura em Austin», diz baixinho. «O meu pai acha que vou para a Baylor, em Waco, e depois para o seminário.»`)],choices:[
 {t:t(`[手艺 30] 拿起铅笔，教他画透视`,`[Craft 30] Pick up a pencil and teach him perspective`,`[Ofício 30] Pegar num lápis e ensinar-lhe perspetiva`),req:()=>S.stats.oficio>=30||NEED(t(`手艺 30`,`Craft 30`,`Ofício 30`)),fx:()=>{S.flags.p2_ldArt=(S.flags.p2_ldArt||0)+1;stat('oficio',1)},next:()=>say(t(`两个消失点`,`Two vanishing points`,`Dois pontos de fuga`),t(`你画了一条地平线、两个消失点。他看了很久：“你学过？”“学过四年，没学完。”“那你教我剩下的。”`,`You draw a horizon and two vanishing points. He stares. "You studied this?" "Four years. Didn't finish." "Then teach me the rest."`,`Desenhas uma linha do horizonte e dois pontos de fuga. Ele fica a olhar. «Estudaste isto?» «Quatro anos. Não acabei.» «Então ensina-me o resto.»`))},
 {t:t(`告诉他们你为什么没读完建筑`,`Tell them why you never finished architecture`,`Contar-lhes porque não acabaste arquitetura`),fx:()=>{stat('saud',2);S.flags.p2_ldTruth=1},next:()=>say(t(`没人住的房子`,`Houses nobody lives in`,`Casas onde ninguém mora`),t(`你说你怕画出来的房子没人住。小戴尔点头，像听到了全世界最合理的理由。汤米问：“那现在呢？”“现在我住在一座别人画的房子里。”`,`You say you were afraid of drawing houses nobody would live in. Little Dale nods as if it's the most sensible reason in the world. Tommy asks, "And now?" "Now I live in a house somebody else drew."`,`Dizes que tinhas medo de desenhar casas onde ninguém fosse morar. O Dale Júnior acena como se fosse a razão mais sensata do mundo. O Tommy pergunta: «E agora?» «Agora moro numa casa que outro desenhou.»`))},
 {t:t(`问汤米：“你自己想去吗？”`,`Ask Tommy: "Do you want to go?"`,`Perguntar ao Tommy: «Tu queres ir?»`),fx:()=>{S.flags.p2_tommyAsk=1},next:()=>say(t(`没人问过`,`Nobody asked`,`Ninguém perguntou`),t(`汤米停下不嚼了。“没人问过我这个，”他说，然后又咬了一大口，“我想想。”`,`Tommy stops chewing. "Nobody ever asked me that," he says, then takes another huge bite. "Lemme think."`,`O Tommy para de mastigar. «Nunca ninguém me perguntou isso», diz, e dá outra dentada enorme. «Deixa-me pensar.»`))}]})},

/* =============== D · Albertina (1) =============== */
{id:'p2_alb1',when:()=>rel('albertina').met&&P2.at(16,2,1)(),run:()=>({title:t(`1958 年的船`,`The boat in 1958`,`O barco de 1958`),meta:P2.M.alb,text:[
 t(`阿尔贝蒂娜从钱包最里层抽出一张照片：一艘白色客轮，栏杆边挤满了戴头巾的女人。“1957 年，法亚尔岛的火山喷了一整年，把我们村子埋了。美国开了个口子，让岛上的人过来。第二年春天，我十二岁，上了这条船。”`,`From the innermost pocket of her purse Albertina draws a photo: a white liner, its rails crowded with women in headscarves. "In '57 the volcano on Faial erupted for a whole year and buried our village. America opened a door for the island people. Next spring I was twelve and I got on this boat."`,`Do bolso mais escondido da carteira, a Albertina tira uma fotografia: um paquete branco, a amurada cheia de mulheres de lenço. «Em 57, o vulcão do Faial esteve um ano inteiro a deitar fogo e enterrou a nossa aldeia. A América abriu uma porta à gente das ilhas. Na primavera seguinte eu tinha doze anos e subi para este barco.»`),
 t(`“船上我妈一直唱一首《查马里塔》，岛上的跳舞歌。第一段我还记得，第二段……”她摇头，“我丈夫会唱，他走了十一年了。明年开春我就八十。死之前，我想再听一次，用岛上的口音。”`,`"On board my mother kept singing a chamarrita, an island dance song. I still have the first verse. The second…" She shakes her head. "My husband knew it. He's been gone eleven years. Come spring I'll be eighty. Before I die I want to hear it once more, in the island accent."`,`«No barco, a minha mãe cantava sempre uma chamarrita, uma moda de baile das ilhas. A primeira quadra ainda sei. A segunda…» Abana a cabeça. «O meu marido sabia. Morreu há onze anos. Na primavera faço oitenta. Antes de morrer queria ouvi-la outra vez, com o sotaque das ilhas.»`)],choices:[
 {t:t(`答应替她找到第二段`,`Promise to find the second verse`,`Prometer encontrar a segunda quadra`),fx:()=>{S.flags.p2_song=1;addTrust('albertina',1)}},
 {t:t(`[乡愁 45] 用里斯本的调子唱你知道的那段`,`[Homesickness 45] Sing the bit you know, Lisbon-style`,`[Saudade 45] Cantar o que sabes, à maneira de Lisboa`),req:()=>S.stats.saud>=45||NEED(t(`乡愁 45`,`Homesickness 45`,`Saudade 45`)),fx:()=>{S.flags.p2_song=1;addLike('albertina',2);S.lusoThisWeek=true},next:()=>say(t(`太里斯本了`,`Too Lisbon`,`Demasiado Lisboa`),t(`她听完笑了：“太里斯本了，像穿着皮鞋跳舞。”可她一直在拍手。`,`She laughs when you finish. "Too Lisbon. Like dancing in city shoes." But she claps the whole way through.`,`Ri-se quando acabas. «Demasiado Lisboa. Como dançar de sapatos de cidade.» Mas bateu palmas do princípio ao fim.`))},
 {t:t(`“八十岁的生日，在我店里办。”`,`"Your eightieth is at my place."`,`«Os teus oitenta fazem-se no meu restaurante.»`),fx:()=>{S.flags.p2_song=1;S.flags.p2_party=1;S.rep+=1},next:()=>say(t(`宾客名单`,`The guest list`,`A lista de convidados`),t(`她拍拍你的脸：“你得请九个老太太，还有席尔瓦先生。他会哭，你别笑他。”`,`She pats your cheek. "Then you invite nine old ladies and Mr. Silva. He'll cry. Don't you laugh at him."`,`Dá-te uma palmadinha na cara. «Então convidas nove velhotas e o senhor Silva. Ele vai chorar. Não te rias dele.»`))}]})},

/* =============== B · Travis (1) =============== */
{id:'p2_travis1',when:()=>rel('travis').met&&P2.at(18,3,2)(),run:()=>({title:t(`没人帮他数数`,`Nobody counting`,`Ninguém a contar`),meta:t(`铁马健身房 · 夜里十一点`,`Iron Mustang Gym · 11 p.m.`,`Ginásio Iron Mustang · 23h`),text:[
 t(`你夜里路过铁马健身房，灯还亮着。特拉维斯一个人在卧推，没人保护，杠铃压在他胸口上，一点一点往下沉。`,`Walking past the Iron Mustang late, you see the lights on. Travis is benching alone, no spotter, and the bar is sinking into his chest an inch at a time.`,`Passas pelo Iron Mustang tarde e as luzes estão acesas. O Travis está no supino sozinho, sem ninguém a ajudar, e a barra vai-lhe afundando o peito centímetro a centímetro.`),
 t(`你把杠铃拉回架上。他躺着喘了很久：“十二个。我爸以前就站在这儿数，数到十二就说：‘博伊德家的人不停在十二。’他八十岁了还在数。数我的钱，数我的地，数我还欠他多少。”`,`You haul the bar back onto the rack. He lies there breathing for a long time. "Twelve. My dad used to stand right there and count. At twelve he'd say, 'Boyds don't stop at twelve.' He's eighty and he's still counting. My money, my land, how much I still owe him."`,`Puxas a barra para o suporte. Ele fica deitado a respirar durante muito tempo. «Doze. O meu pai punha-se ali a contar. Aos doze dizia: "Os Boyd não param nos doze." Tem oitenta anos e ainda conta. O meu dinheiro, as minhas terras, quanto ainda lhe devo.»`)],choices:[
 {t:t(`替他数完这一组`,`Count out the rest of his set`,`Contar-lhe o resto da série`),fx:()=>{P2.tv(1);addTrust('travis',1)},next:()=>say(t(`够了`,`Enough`,`Chega`),t(`你数到十五，他停了。“够了，”他说。这是你第一次听他说这两个字。`,`At fifteen he stops. "That's enough," he says. It's the first time you've heard him say it.`,`Aos quinze, para. «Chega», diz. É a primeira vez que lhe ouves essa palavra.`))},
 {t:t(`问他：“你买那块地，也是为了让他数？”`,`Ask: "Is that land for him to count too?"`,`Perguntar: «Aquele terreno também é para ele contar?»`),req:()=>(S.flags.rozHint||0)>=1||S.stats.tex>=30||NEED(t(`罗兹的提示或德州味 30`,`Roz's hint or Texanness 30`,`A pista da Roz ou Texanidade 30`)),fx:()=>{P2.tv(1)},next:()=>say(t(`毛巾`,`The towel`,`A toalha`),t(`他坐起来，用毛巾捂住脸，很久没拿下来。“你舅舅也这样，”他说，“专问不该问的。”`,`He sits up and presses a towel to his face and keeps it there a long time. "Your uncle was like that," he says. "Always asking what he shouldn't."`,`Senta-se e encosta uma toalha à cara, e deixa-a lá muito tempo. «O teu tio era assim», diz. «Sempre a perguntar o que não devia.»`))},
 {t:`[${faceWord()}] `+t(`拍拍他的肩：“以后我当你的保护？”`,`Slap his shoulder: "Want me to spot you from now on?"`,`Dar-lhe uma palmada no ombro: «Queres que seja eu a ajudar-te daqui em diante?»`),req:CHARM_REQ(50),fx:()=>{flirt();addLike('travis',1)},next:()=>say(t(`又变回来了`,`Back to normal`,`De volta ao normal`),t(`他笑了，又变回那个特拉维斯：“小心点，葡萄牙人，镇上会说闲话的。”`,`He grins and he's the old Travis again. "Careful, Portugal. Folks'll talk."`,`Sorri e volta a ser o Travis de sempre. «Cuidado, Portugal. A malta vai falar.»`))},
 {t:t(`什么都不说，替他关了灯`,`Say nothing; turn off the lights for him`,`Não dizer nada; apagar-lhe as luzes`),next:()=>say(t(`门口`,`At the door`,`À porta`),t(`你在门口回头。他还躺在那儿看着天花板，像在等谁来数。`,`At the door you look back. He's still lying there staring at the ceiling, as if waiting for someone to count.`,`À porta olhas para trás. Continua deitado a olhar para o teto, como se esperasse que alguém contasse.`))}]})},

/* =============== C · Earl (1) =============== */
{id:'p2_earl1',when:P2.at(23,6,2),run:()=>{rel('earl').met=true;return {title:t(`那颗星`,`The star`,`A estrela`),meta:t(`孤星酒吧 · 周六夜`,`The Lone Star · Saturday night`,`O Lone Star · sábado à noite`),text:[
 t(`厄尔第三次把杯子掉在地上。他扶着吧台站了很久，从口袋里摸出一粒小白药片压在舌头下面。“别告诉乔琳。”`,`Earl drops a glass for the third time. He holds on to the bar a long while, then fishes out a little white pill and puts it under his tongue. "Don't tell Jolene."`,`O Earl deixa cair um copo pela terceira vez. Agarra-se ao balcão muito tempo e depois tira do bolso um comprimido branco e põe-no debaixo da língua. «Não digas à Jolene.»`),
 t(`“1998 年夏天，若泽被汉克开除，没地方住。我让他睡在后屋，睡了三个月。他给我画了外面那块招牌——那颗星是他画的。后来他要在老兵会上把厂里的水说出来，我让他闭嘴。我说一个没身份的外国人斗不过汉克·博伊德。”厄尔看着招牌，“他听了我的。我后悔了二十七年。”`,`"Summer of '98, Hank fired José and he had nowhere to sleep. I put him in the back room three months. He painted me that sign out front — the star's his. Then he wanted to stand up at the VFW and tell about the water at the plant, and I told him to shut his mouth. Said a foreigner with no papers don't beat Hank Boyd." Earl looks at the sign. "He listened to me. I been sorry twenty-seven years."`,`«No verão de 98, o Hank despediu o José e ele não tinha onde dormir. Pu-lo no quarto das traseiras três meses. Pintou-me aquela tabuleta lá fora — a estrela é dele. Depois quis levantar-se na associação dos veteranos e contar da água da fábrica, e eu mandei-o calar. Disse-lhe que um estrangeiro sem papéis não ganha ao Hank Boyd.» O Earl olha para a tabuleta. «Ele deu-me ouvidos. Há vinte e sete anos que me arrependo.»`)],choices:[
 {t:t(`替他看一晚上吧台`,`Mind the bar for him tonight`,`Ficar ao balcão por ele esta noite`),fx:()=>{addTrust('earl',2);stat('tex',1);S.flags.p2_earlBar=1},next:()=>say(t(`打碎两个`,`Two broken`,`Dois partidos`),t(`你倒了一晚上啤酒，打碎两个杯子。打烊时厄尔说：“比若泽强。他打碎了五个。”`,`You pour beer all night and break two glasses. At closing Earl says, "Better than José. He broke five."`,`Tiras cerveja a noite toda e partes dois copos. Ao fechar, o Earl diz: «Melhor que o José. Ele partiu cinco.»`))},
 {t:t(`劝他去找汉娜医生`,`Get him to see Dr. Hannah`,`Convencê-lo a ir à Dra. Hannah`),req:()=>rel('hannah').met||NEED(t(`认识汉娜医生`,`Know Dr. Hannah`,`Conhecer a Dra. Hannah`)),fx:()=>{S.flags.p2_earlDoc=1;addTrust('earl',1)},next:()=>say(t(`北方姑娘`,`The Yankee girl`,`A rapariga do Norte`),t(`“那个北方姑娘？”他哼了一声。第二周，你在诊所门口看见了他的老福特。`,`"That Yankee girl?" he snorts. The next week you see his old Ford outside the clinic.`,`«Aquela rapariga do Norte?», bufa. Na semana seguinte vês o velho Ford dele à porta da clínica.`))},
 {t:t(`“舅舅不怪你。他把店开在了你隔壁。”`,`"He didn't blame you. He opened his shop next door to you."`,`«Ele não te culpava. Abriu o restaurante ao teu lado.»`),req:P2.letters(6),fx:()=>{addLike('earl',2);stat('saud',2)},next:()=>say(t(`犟驴`,`Mule`,`Teimoso`),t(`厄尔擦了很久同一个杯子。“那头犟驴，”他说，声音哑了。`,`Earl polishes the same glass a long time. "That stubborn mule," he says, and his voice cracks.`,`O Earl limpa o mesmo copo durante muito tempo. «Aquele teimoso», diz, e a voz falha-lhe.`))}]}}},

/* =============== F · ranch (2) =============== */
{id:'p2_ranch2',when:()=>!!S.flags.ev_p2_ranch1&&P2.at(21,4,1)(),run:()=>({title:t(`南边的牧场`,`The south pasture`,`O pasto do sul`),meta:P2.M.ranch,text:[
 t(`旱灾过去了，账还在。休斯敦来了个穿新靴子的中介，要买雷耶斯牧场南边的草场——连那口封着的井一起，价钱高得不像话。`,`The drought is over; the bills aren't. A broker from Houston in brand-new boots wants to buy the Reyes south pasture — sealed well and all — for a price that makes no sense.`,`A seca passou; as contas não. Um intermediário de Houston, de botas novas, quer comprar o pasto do sul dos Reyes — com o poço tapado e tudo — por um preço que não faz sentido.`),
 t(`贝托把报价单折了又折：“一个连牛都没养过的公司，买一块不能喝水的地。”露西娅说：“爸，银行下个月就来。”`,`Beto folds the offer smaller and smaller. "A company that never raised a cow, buying land you can't drink from." Lucía says, "Papá, the bank comes next month."`,`O Beto dobra a proposta cada vez mais pequena. «Uma empresa que nunca criou uma vaca, a comprar terra de onde não se pode beber.» A Lucía diz: «Pai, o banco vem no mês que vem.»`)],choices:[
 {t:t(`告诉贝托：特拉维斯不是在买草`,`Tell Beto: Travis isn't buying grass`,`Dizer ao Beto: o Travis não está a comprar erva`),req:()=>(S.flags.rozHint||0)>=1||NEED(t(`罗兹的提示`,`Roz's hint`,`A pista da Roz`)),fx:()=>{S.flags.p2_beto='held';addTrust('beto',2)},next:()=>say(t(`炉子`,`The stove`,`O fogão`),t(`贝托看了你很久，把报价单塞进炉子。“若泽也是这么说的，”他说，“那年他也站在这儿。”`,`Beto looks at you a long time, then feeds the offer to the stove. "José said the same," he says. "Stood right where you're standing."`,`O Beto olha para ti muito tempo e depois mete a proposta no fogão. «O José disse o mesmo», diz. «Estava aí, onde tu estás.»`))},
 {t:t(`[手艺 35] 接下秋季拍卖会的烧烤，钱全归牧场`,`[Craft 35] Cook the fall auction for free; all takings to the ranch`,`[Ofício 35] Cozinhar no leilão de outono de graça; tudo para o rancho`),req:()=>S.stats.oficio>=35||NEED(t(`手艺 35`,`Craft 35`,`Ofício 35`)),fx:()=>{S.flags.p2_beto='held';stat('oficio',1);addTrust('lucia',1);S.rep+=1},next:()=>say(t(`拍卖会`,`Auction day`,`Dia de leilão`),t(`两百份牛胸肉。牛的成交价比往年高了一成，有人说是因为买家都吃饱了。`,`Two hundred plates of brisket. The cattle sell ten percent above last year; folks say it's because the buyers were well fed.`,`Duzentos pratos de peito fumado. O gado vende-se dez por cento acima do ano passado; dizem que é porque os compradores estavam de barriga cheia.`))},
 {t:t(`那笔借款不用还了`,`Tell them to forget the loan`,`Dizer-lhes que esqueçam o empréstimo`),req:()=>!!S.flags.p2_betoLoan||NEED(t(`夏天借过钱给他们`,`You lent them money in summer`,`Emprestaste-lhes dinheiro no verão`)),fx:()=>{S.flags.p2_beto='held';S.flags.p2_betoLoan=0;addTrust('beto',1)},next:()=>say(t(`三百块`,`Three hundred`,`Trezentos`),t(`“我不收礼。”“这不是礼，是若泽欠你的三百块，加利息。”贝托愣了一下，笑出了声。你第一次听见他笑。`,`"I don't take gifts." "It's not a gift. It's the three hundred José owed you, with interest." Beto stares, then laughs out loud. It's the first time you've heard him laugh.`,`«Não aceito presentes.» «Não é presente. São os trezentos que o José te devia, com juros.» O Beto fica a olhar e depois ri-se alto. É a primeira vez que o ouves rir.`))},
 {t:t(`这是他们家的事，不插手`,`It's their business; stay out of it`,`É assunto deles; não te meteres`),fx:()=>{S.flags.p2_beto='option'},next:()=>say(t(`优先购买权`,`The option`,`O direito de preferência`),t(`一周后你听说，贝托签了一份优先购买权：不是卖，只是答应要卖就先卖给他们。露西娅说她爸那天一个人在井边坐到天亮。`,`A week later you hear Beto signed an option: not a sale, just a promise that if he sells, he sells to them first. Lucía says her father sat by the well alone until dawn.`,`Uma semana depois sabes que o Beto assinou um direito de preferência: não é venda, só a promessa de que, se vender, vende-lhes primeiro. A Lucía diz que o pai ficou sozinho junto ao poço até de manhã.`))}]})},

/* =============== D · Albertina (2) =============== */
{id:'p2_alb2',when:()=>!!S.flags.ev_p2_alb1&&P2.at(26,7,1)(),run:()=>({title:t(`第二段`,`The second verse`,`A segunda quadra`),meta:P2.M.alb,text:[
 t(`你问遍了教堂里的老人。席尔瓦先生记得调子，不记得词；另一位太太记得词，却坚持那是另一首歌。`,`You've asked every old soul at church. Mr. Silva has the tune but not the words; another lady has the words but swears they belong to a different song.`,`Perguntaste a todos os velhos da igreja. O senhor Silva sabe a música mas não a letra; outra senhora sabe a letra mas jura que é de outra canção.`),
 t(`阿尔贝蒂娜拿出一张七十八转的老唱片，裂了一道缝：“我丈夫在波士顿买的。家里早没唱机了。”`,`Albertina brings out an old 78 with a crack across it. "My husband bought it in Boston. We haven't had a player in years."`,`A Albertina traz um disco antigo de 78 rotações, rachado. «O meu marido comprou-o em Boston. Há anos que não temos gira-discos.»`)],choices:[
 {t:t(`打电话回里斯本，请妈妈问问楼下那位皮库岛来的太太`,`Call Lisbon; ask Mom to try the lady downstairs from Pico`,`Ligar para Lisboa; pedir à mãe que pergunte à senhora do Pico do rés-do-chão`),req:()=>(S.flags.p2_calls||0)>=2||S.stats.saud>=40||NEED(t(`常给家里打电话或乡愁 40`,`Call home often or Homesickness 40`,`Ligar muito para casa ou Saudade 40`)),fx:()=>{S.flags.p2_songSrc='lisbon';stat('saud',3);S.lusoThisWeek=true},next:()=>say(t(`录音`,`The recording`,`A gravação`),t(`三天后鲁伊发来一段录音：楼下的老太太坐在窗边，唱得有点喘，第二段一个字不差。背景里，妈妈在跟着打拍子。`,`Three days later Rui sends a recording: the old lady downstairs by her window, a little out of breath, second verse word for word. In the background, Mom is clapping along.`,`Três dias depois o Rui manda uma gravação: a velhota do rés-do-chão à janela, um pouco ofegante, a segunda quadra palavra por palavra. Ao fundo, a mãe bate palmas.`))},
 {t:t(`去奥斯汀，找批发市场那位亚速尔老板`,`Go to Austin and find the Azorean at the wholesale market`,`Ir a Austin procurar o açoriano do mercado abastecedor`),req:()=>S.course.drive>=1||S.stats.tex>=30||NEED(t(`驾驶课 1 或德州味 30`,`Driving lesson 1 or Texanness 30`,`Aula de condução 1 ou Texanidade 30`)),fx:()=>{S.flags.p2_songSrc='austin';stat('tex',2)},next:()=>say(t(`鳕鱼干中间`,`Among the salt cod`,`No meio do bacalhau`),t(`老板听你哼了两句，把店门一关，站在鳕鱼干中间唱完了整首。“我奶奶是法亚尔人，”他说，“生日那天我来。”`,`The owner hears you hum two lines, shuts the shop door and sings the whole thing standing among the salt cod. "My grandmother was from Faial," he says. "I'll be at that birthday."`,`O dono ouve-te trautear dois versos, fecha a porta da loja e canta a moda inteira no meio do bacalhau. «A minha avó era do Faial», diz. «Nesse aniversário eu vou.»`))},
 {t:t(`请凯尔把唱片修好，翻录出来`,`Ask Kyle to fix the record and copy it`,`Pedir ao Kyle que arranje o disco e o grave`),req:()=>rel('kyle').met||NEED(t(`认识凯尔`,`Know Kyle`,`Conhecer o Kyle`)),fx:()=>{S.flags.p2_songSrc='kyle';addLike('kyle',1)},next:()=>say(t(`拼起来的唱机`,`A patched-up player`,`Um gira-discos remendado`),t(`凯尔用胶水、一根缝衣针和一台修农机剩下的小马达拼了一台唱机。裂缝每转一圈“咔”一声，像有人在敲船舷。`,`Kyle builds a player out of glue, a sewing needle and a little motor left over from a tractor job. The crack clicks every turn, like someone knocking on a ship's rail.`,`O Kyle monta um gira-discos com cola, uma agulha de costura e um motorzinho que sobrou de um trator. A racha estala a cada volta, como alguém a bater na amurada.`))},
 {t:t(`网上随便找一段录音`,`Just find something online`,`Procurar uma gravação qualquer na internet`),fx:()=>{S.flags.p2_songSrc='net'},next:()=>say(t(`也算葡语`,`Portuguese, sort of`,`Português, mais ou menos`),t(`你找到一段录音。唱的人是巴西人。也算葡语。`,`You find a recording. The singer is Brazilian. Still Portuguese, sort of.`,`Encontras uma gravação. Quem canta é brasileiro. Sempre é português, mais ou menos.`))}]})},

/* =============== E · kids (2) =============== */
{id:'p2_kids2',when:()=>!!S.flags.ev_p2_kids1&&P2.at(27,6,2)(),run:()=>({title:t(`后门的背包`,`A backpack at the back door`,`Uma mochila à porta das traseiras`),meta:P2.M.kids,text:[
 t(`夜里十一点有人敲后门。小戴尔背着书包站在北风里，眼镜上全是雾。`,`Eleven at night, a knock at the back door. Little Dale stands in the norther with his backpack on, glasses fogged white.`,`Onze da noite, batem à porta das traseiras. O Dale Júnior está no vento norte de mochila às costas, os óculos embaciados.`),
 t(`“奥斯汀的提前录取信，我考上了。他看见了。”他的声音很平，“他说金凯德家的男人不画房子，要画也只画教堂。我说那我就画教堂。他把速写本扔进了壁炉。我能在你这儿睡一晚吗？若泽以前不也睡在厄尔那儿？”`,`"Early admission to Austin. I got in. He saw the letter." His voice is flat. "He said Kincaid men don't draw houses, and if they draw anything it's churches. I said fine, I'll draw churches. He threw my sketchbook in the fireplace. Can I sleep here tonight? José slept at Earl's once, didn't he?"`,`«Admissão antecipada em Austin. Entrei. Ele viu a carta.» A voz é seca. «Disse que os homens Kincaid não desenham casas, e se desenham alguma coisa é igrejas. Eu disse que então desenhava igrejas. Atirou o meu caderno para a lareira. Posso dormir aqui esta noite? O José também dormiu em casa do Earl, não foi?»`)],choices:[
 {t:t(`让他睡下，你亲自给戴尔牧师打电话报平安`,`Let him stay, and call Pastor Dale yourself to say he's safe`,`Deixá-lo ficar e ligar tu ao Pastor Dale a dizer que ele está bem`),fx:()=>{S.flags.p2_ldNight='called';addTrust('dale',1)},next:()=>say(t(`电话`,`The call`,`A chamada`),t(`电话响了一声就接了。牧师沉默了很久：“他吃饭了吗？”“吃了。”“……谢谢你。”他挂了，没说要来接。`,`He picks up on the first ring. A long silence. "Has he eaten?" "He has." "…Thank you." He hangs up. He doesn't offer to come.`,`Atende ao primeiro toque. Um silêncio comprido. «Ele já comeu?» «Já.» «…Obrigado.» Desliga. Não diz que vem buscá-lo.`))},
 {t:t(`他求你别打电话，你答应了`,`He begs you not to call; you agree`,`Ele pede-te que não ligues; aceitas`),fx:()=>{S.flags.p2_ldNight='hid';addTrust('dale',-1)},next:()=>say(t(`凌晨两点`,`Two a.m.`,`Duas da manhã`),t(`他在长凳上睡着了，手里攥着从火里抢出来的半本速写本。凌晨两点，牧师的车在主街上慢慢开过去，又慢慢开回来。`,`He falls asleep on the bench holding the half sketchbook he pulled out of the fire. At two a.m. the pastor's car crawls down Main Street, and crawls back.`,`Adormece no banco agarrado ao meio caderno que salvou do fogo. Às duas da manhã, o carro do pastor passa devagar pela rua principal, e volta devagar.`))},
 {t:t(`打给梅根`,`Call Megan`,`Ligar à Megan`),req:()=>rel('megan').met||NEED(t(`认识梅根`,`Know Megan`,`Conhecer a Megan`)),fx:()=>{S.flags.p2_ldNight='megan';addTrust('megan',1)},next:()=>say(t(`姐弟`,`Brother and sister`,`Irmão e irmã`),t(`梅根十分钟就到了，睡衣外面套着唱诗班的长袍。姐弟俩坐到凌晨。你听见她说：“我晚了七年才走。你别学我。”`,`Megan is there in ten minutes, choir robe thrown over her pajamas. The two of them sit up till the small hours. You hear her say, "I waited seven years too long to leave. Don't you copy me."`,`A Megan chega em dez minutos, a túnica do coro por cima do pijama. Os dois ficam até de madrugada. Ouves-la dizer: «Esperei sete anos a mais para sair. Não me imites.»`))},
 {t:t(`[手艺 35] 连夜帮他把烧坏的几页重画出来`,`[Craft 35] Help him redraw the burned pages overnight`,`[Ofício 35] Ajudá-lo a redesenhar as páginas queimadas durante a noite`),req:()=>S.stats.oficio>=35||NEED(t(`手艺 35`,`Craft 35`,`Ofício 35`)),fx:()=>{S.flags.p2_ldNight='drew';S.flags.p2_ldArt=(S.flags.p2_ldArt||0)+1;stat('oficio',1)},next:()=>say(t(`十二张`,`Twelve sheets`,`Doze folhas`),t(`天亮时桌上摊着十二张新画。最上面一张是圣鲁伊斯浸信会教堂，画得一丝不苟。`,`By dawn twelve new drawings cover the table. On top: San Luís Baptist Church, drawn with perfect care.`,`De manhã há doze desenhos novos na mesa. Por cima: a Igreja Batista de San Luís, desenhada com todo o cuidado.`))}]})},

/* =============== B · Travis (2) =============== */
{id:'p2_travis2',when:()=>!!S.flags.ev_p2_travis1&&P2.at(30,3,2)(),run:()=>({title:t(`沟里的皮卡`,`The truck in the ditch`,`A carrinha na valeta`),meta:P2.M.travis,text:[
 t(`冰还没化干净。回家路上，你看见特拉维斯的黑色皮卡斜在沟里，双闪一明一灭。他的手机亮着：休斯敦，第七次来电。`,`The ice isn't all gone. On the way home you see Travis's black pickup nose-down in the ditch, hazards blinking. His phone is lit: Houston, seventh call.`,`O gelo ainda não derreteu todo. A caminho de casa vês a carrinha preta do Travis de nariz na valeta, os quatro piscas a piscar. O telemóvel dele está aceso: Houston, sétima chamada.`),
 t(`“别看。”他把手机扣下，“债。我爸的厂子留下的，我接过来，又借了更多来还。砂场是我最后一张牌。”半小时后，他手下的工程师罗兹开着公司的皮卡来了。她叫他“特拉维”，像叫一个不争气的弟弟。“全镇只有她敢跟我说不，”他小声说，“我付她工资，就是为了这个。”`,`"Don't look." He turns the phone face down. "Debt. My dad's plant left it; I took it on and borrowed more to pay it. The sand yard's my last card." Half an hour later his engineer Roz pulls up in the company truck. She calls him "Trav," like a kid brother who keeps disappointing her. "Only person in town who tells me no," he mutters. "That's what I pay her for."`,`«Não olhes.» Vira o telemóvel ao contrário. «Dívidas. A fábrica do meu pai deixou-as; fiquei com elas e pedi mais para as pagar. O estaleiro de areia é a minha última carta.» Meia hora depois chega a engenheira dele, a Roz, na carrinha da empresa. Chama-lhe «Trav», como a um irmão mais novo que a desilude sempre. «A única pessoa da vila que me diz que não», murmura ele. «É para isso que lhe pago.»`)],choices:[
 {t:t(`帮罗兹把车拖出来`,`Help Roz tow him out`,`Ajudar a Roz a rebocá-lo`),req:()=>S.course.drive>=1||S.stats.tex>=30||NEED(t(`驾驶课 1 或德州味 30`,`Driving lesson 1 or Texanness 30`,`Aula de condução 1 ou Texanidade 30`)),fx:()=>{P2.tv(1);addTrust('roz',1)},next:()=>say(t(`一百块`,`A hundred bucks`,`Cem dólares`),t(`车出来了。特拉维斯想塞给你一百块，罗兹按住他的手：“别什么都用钱。”`,`The truck comes out. Travis tries to stuff a hundred in your hand; Roz holds his wrist. "Not everything's money, Trav."`,`A carrinha sai. O Travis tenta meter-te cem dólares na mão; a Roz segura-lhe o pulso. «Nem tudo é dinheiro, Trav.»`))},
 {t:t(`问罗兹：“你为什么还替他干？”`,`Ask Roz: "Why do you still work for him?"`,`Perguntar à Roz: «Porque é que ainda trabalhas para ele?»`),fx:()=>{S.flags.p2_rozWhy=1;addTrust('roz',1)},next:()=>say(t(`欠的东西`,`What people owe`,`O que se deve`),t(`她把拖车绳卷好：“高中时全班只有他不笑我想当工程师。他爸不肯，是他去求他爸给我出的学费。”她看着那辆皮卡，“人欠的东西，比钱难还。”`,`She coils the tow rope. "In high school he was the only one who didn't laugh when I said engineer. His daddy wouldn't pay; Trav begged him till he paid my tuition." She looks at the truck. "Some debts are harder than money."`,`Enrola a corda de reboque. «No liceu foi o único que não se riu quando eu disse engenheira. O pai não queria pagar; o Trav pediu-lhe até ele pagar as minhas propinas.» Olha para a carrinha. «Há dívidas mais difíceis que dinheiro.»`))},
 {t:t(`“你可以不打这张牌。”`,`"You don't have to play that card."`,`«Não tens de jogar essa carta.»`),fx:()=>{P2.tv(1)},next:()=>say(t(`说得轻巧`,`Easy to say`,`Fácil de dizer`),t(`特拉维斯笑了，笑得很难看：“你说得轻巧。你舅舅也说过这句。”`,`Travis laughs, and it's an ugly laugh. "Easy for you. Your uncle said that too."`,`O Travis ri-se, um riso feio. «Para ti é fácil. O teu tio também disse isso.»`))},
 {t:t(`开走，让他们自己处理`,`Drive on and let them handle it`,`Seguir caminho e deixá-los tratar disso`),next:()=>say(t(`后视镜`,`Rear-view mirror`,`Retrovisor`),t(`后视镜里，两个人影在双闪灯里一明一灭。`,`In the mirror two figures flicker on and off in the hazard lights.`,`No retrovisor, duas figuras acendem e apagam ao ritmo dos piscas.`))}]})},

/* =============== A · Rui (1) =============== */
{id:'p2_rui_call',when:P2.at(32,4,2),run:()=>{const c=P2.contact();
 const ch=[];
 if(c>=5)ch.push({t:t(`“来吧。我去奥斯汀接你。”`,`"Come. I'll pick you up in Austin."`,`«Vem. Vou buscar-te a Austin.»`),fx:()=>{S.flags.p2_rui='coming';log('鲁伊要来德州了','Rui is coming to Texas','O Rui vem ao Texas')},next:()=>say(t(`登机牌`,`Boarding pass`,`Cartão de embarque`),t(`他发来一张登机牌的照片，后面跟着两个字：“别笑。”`,`He sends a photo of his boarding pass, then: "Don't laugh."`,`Manda uma fotografia do cartão de embarque e depois: «Não te rias.»`))});
 else ch.push({t:t(`给他买机票（$650）`,`Buy his ticket ($650)`,`Comprar-lhe o bilhete ($650)`),req:MONEY(650),fx:()=>{S.cash-=650;S.flags.p2_rui='coming';log('给鲁伊买了来德州的机票','Bought Rui a ticket to Texas','Compraste ao Rui um bilhete para o Texas')},next:()=>say(t(`登机牌`,`Boarding pass`,`Cartão de embarque`),t(`他沉默了一会儿：“你这是在德州发财了？”“没有。”“那你就是傻。”他还是收下了。`,`A pause. "Struck it rich in Texas, have you?" "No." "Then you're an idiot." He takes it anyway.`,`Uma pausa. «Enriqueceste no Texas, foi?» «Não.» «Então és parvo.» Aceita na mesma.`))},
  {t:t(`打视频给妈妈，让她亲自命令他来`,`Video-call Mom and let her order him to go`,`Fazer videochamada à mãe e deixá-la mandá-lo ir`),req:()=>(S.flags.p2_calls||0)>=1||S.stats.saud>=45||NEED(t(`给家里打过电话或乡愁 45`,`Have called home or Homesickness 45`,`Já ligaste para casa ou Saudade 45`)),fx:()=>{S.flags.p2_rui='coming';S.flags.p2_momPaid=1;stat('saud',3);S.lusoThisWeek=true},next:()=>say(t(`命令`,`Orders`,`Ordens`),t(`妈妈在病床上坐直了：“鲁伊，抽屉里那个信封，拿去买票。”鲁伊说那是她的葬礼钱。“那就别让我用上。”`,`Mom sits up in the hospital bed. "Rui, the envelope in the drawer. Buy the ticket." Rui says that's her funeral money. "Then don't make me need it."`,`A mãe endireita-se na cama do hospital. «Rui, o envelope da gaveta. Compra o bilhete.» O Rui diz que é o dinheiro do funeral dela. «Então não me faças precisar dele.»`))});
 ch.push({t:t(`“等春天，来看圣安东尼节吧。”`,`"Wait for spring. Come for the Santo António."`,`«Espera pela primavera. Vem ao Santo António.»`),fx:()=>{S.flags.p2_rui='later'},next:()=>say(t(`春天再说`,`Spring, then`,`Na primavera, então`),t(`“春天再说，”他说。你听得出来，他松了口气，也有点失望。`,`"Spring, then," he says. You can hear he's relieved, and a little let down.`,`«Na primavera, então», diz. Percebes que está aliviado, e um pouco desiludido.`))});
 return {title:t(`鲁伊的消息`,`A message from Rui`,`Uma mensagem do Rui`),meta:t(`里斯本 · 凌晨`,`Lisbon · small hours`,`Lisboa · madrugada`),text:[
  c>=5?t(`“妈让我去德州看你。你寄回来的钱，她留了一张机票的数：‘去看看你哥，看看泽的店，回来讲给我听。’卢尔德斯姨妈来陪她一星期。”`,`"Mom wants me to go see you in Texas. From what you sent she put aside the price of a ticket: 'Go see your brother, see Zé's shop, come back and tell me.' Aunt Lurdes will stay with her a week."`,`«A mãe quer que eu te vá ver ao Texas. Do que mandaste, pôs de parte o preço de um bilhete: "Vai ver o teu irmão, vai ver o restaurante do Zé, e depois conta-me." A tia Lurdes fica com ela uma semana.»`)
  :c>=2?t(`“妈让我去看你。卢尔德斯姨妈能来陪她一星期。可机票六百五，我这个月的工资都给了药房。”`,`"Mom wants me to go see you. Aunt Lurdes can stay with her a week. But the ticket's six-fifty and this month's pay all went to the pharmacy."`,`«A mãe quer que eu te vá ver. A tia Lurdes pode ficar com ela uma semana. Mas o bilhete são seiscentos e cinquenta e o ordenado deste mês foi todo para a farmácia.»`)
  :t(`“妈问你是不是忘了里斯本的区号。”鲁伊停了一下，“她让我去看看你还活着没有。我没钱，也没那么想去。”`,`"Mom asks if you've forgotten Lisbon's dialing code." Rui pauses. "She wants me to go check you're still alive. I've got no money, and I'm not that keen."`,`«A mãe pergunta se te esqueceste do indicativo de Lisboa.» O Rui faz uma pausa. «Quer que eu vá ver se ainda estás vivo. Não tenho dinheiro, nem tenho assim tanta vontade.»`)],choices:ch};
}},

/* =============== A · Rui (2) =============== */
{id:'p2_rui_arrive',when:()=>S.flags.p2_rui==='coming'&&P2.at(33,5,1)(),run:()=>{const p=P2.partner();
 const T=[t(`鲁伊从灰狗巴士上下来，背着你当年那只帆布包——他从你床底下翻出来的。他看了看主街，看了看水塔，又看了看你。`,`Rui climbs off the Greyhound with your old canvas bag on his back — he dug it out from under your bed. He looks at Main Street, at the water tower, at you.`,`O Rui sai do autocarro Greyhound com o teu velho saco de lona às costas — foi buscá-lo debaixo da tua cama. Olha para a rua principal, para a torre da água, para ti.`),
  S.muscle>=3?t(`“你这胳膊是怎么回事？”他捏了一下，“妈要是看见，会以为你在这边搬鱼。”`,`"What happened to your arms?" He squeezes one. "If Mom sees these she'll think you're hauling fish out here."`,`«O que é que aconteceu a esses braços?» Aperta-te um. «Se a mãe os vê, pensa que andas aqui a carregar peixe.»`):t(`“你瘦了，”他说，“妈让我检查你吃没吃饭。”`,`"You've got thin," he says. "Mom told me to check you're eating."`,`«Estás mais magro», diz. «A mãe mandou-me ver se comes.»`),
  {'淡':t(`你一开口，他就笑了：“你说葡语怎么也带牛仔味儿了？”`,`The moment you speak he laughs. "Even your Portuguese sounds like a cowboy now."`,`Mal abres a boca, ri-se. «Até o teu português tem sotaque de cowboy.»`),'浓':t(`“你英语还是这么烂，”他说，“好，我放心了。”`,`"Your English is still terrible," he says. "Good. That's a relief."`,`«O teu inglês continua péssimo», diz. «Ainda bem. Fico mais descansado.»`)}[S.accent]||t(`你在两种语言之间换来换去。他看你的眼神，像在看一个陌生人练习当你。`,`You switch back and forth between two languages. He watches you like a stranger practicing to be you.`,`Saltas entre duas línguas. Ele olha para ti como para um estranho a ensaiar ser tu.`)];
 if(S.rep>=40)T.push(t(`从车站走回店里，七个人跟你打招呼，叫的都是你的名字。鲁伊一个一个数着。`,`Walking back from the station, seven people say hello, all by your name. Rui counts every one.`,`No caminho da estação, sete pessoas cumprimentam-te, todas pelo nome. O Rui conta uma a uma.`));
 if(p)T.push(t(`${SH(p)}在店门口等着。鲁伊用葡语小声问：“这是……？”你还没想好怎么回答。`,`${SH(p)} is waiting outside the shop. Rui whispers in Portuguese, "Is this…?" You haven't worked out the answer yet.`,`${SH(p)} está à espera à porta do restaurante. O Rui pergunta baixinho em português: «Isto é…?» Ainda não sabes o que responder.`));
 const ch=[
  {t:t(`[手艺 35] 让他在烤架上站一个午市`,`[Craft 35] Put him on the grill for a lunch rush`,`[Ofício 35] Pô-lo na grelha num almoço`),req:()=>S.stats.oficio>=35||NEED(t(`手艺 35`,`Craft 35`,`Ofício 35`)),fx:()=>{S.flags.p2_ruiSaw='grill';S.rep+=1;stat('oficio',1)},next:()=>say(t(`午市`,`Lunch rush`,`Hora de almoço`),t(`第一条沙丁鱼他烤焦了，第二条烤得像外婆的。收工时他满头大汗：“原来你一天天就干这个。”`,`He burns the first sardine; the second tastes like Grandma's. At the end he's dripping. "So this is what you do all day."`,`Queima a primeira sardinha; a segunda sabe à da avó. No fim está a pingar. «Então é isto que fazes o dia inteiro.»`))},
  {t:t(`带他去孤星酒吧见厄尔`,`Take him to meet Earl at the Lone Star`,`Levá-lo ao Lone Star para conhecer o Earl`),fx:()=>{S.flags.p2_ruiSaw='earl';addLike('earl',1)},next:()=>say(t(`又来一个`,`Another one`,`Mais um`),t(`厄尔看了他很久：“又来一个。上帝啊。”然后倒了三杯，自己喝了一杯。鲁伊说，这是他下飞机以后第一次觉得被欢迎。`,`Earl looks him over a long time. "Another one. Lord." He pours three and drinks one himself. Rui says it's the first time since the plane he's felt welcome.`,`O Earl mede-o muito tempo. «Mais um. Valha-me Deus.» Serve três copos e bebe um. O Rui diz que é a primeira vez desde o avião que se sente bem-vindo.`))},
  {t:t(`带他去教堂见阿尔贝蒂娜`,`Take him to church to meet Albertina`,`Levá-lo à igreja para conhecer a Albertina`),fx:()=>{S.flags.p2_ruiSaw='albertina';addLike('albertina',1);stat('saud',3);S.lusoThisWeek=true},next:()=>say(t(`另一个孩子`,`The other child`,`O outro filho`),t(`阿尔贝蒂娜捧着他的脸看了半天：“费尔南达的另一个孩子。也太瘦。”她塞给他一整盒甜面包，让他带回里斯本。`,`Albertina holds his face and studies it. "Fernanda's other one. Too thin as well." She presses a whole box of sweet bread on him to take back to Lisbon.`,`A Albertina segura-lhe a cara e estuda-a. «O outro filho da Fernanda. Também magro de mais.» Dá-lhe uma caixa inteira de massa sovada para levar para Lisboa.`))}];
 if(p)ch.push({t:t(`让${SH(p)}带你们去最喜欢的地方`,`Let ${SH(p)} take you both somewhere they love`,`Deixar ${SH(p)} levar-vos a um sítio de que gosta`),req:()=>rel(p).like>=5||NEED(t(`好感 5`,`Affection 5`,`Afeto 5`)),fx:()=>{S.flags.p2_ruiSaw='partner';addLike(p,1)},next:()=>say(t(`回来的路上`,`On the way back`,`No regresso`),t(`回来的路上，鲁伊说：“妈会喜欢的。”停了一下，“但你得自己跟她说。”`,`On the way back Rui says, "Mom would like this." A pause. "But you have to tell her yourself."`,`No regresso, o Rui diz: «A mãe ia gostar.» Uma pausa. «Mas tens de ser tu a contar-lhe.»`))});
 return {title:t(`灰狗巴士`,`The Greyhound`,`O autocarro`),meta:P2.M.rui,text:T,choices:ch};
}},

/* =============== A · Rui (3) =============== */
{id:'p2_rui_talk',when:()=>!!S.flags.ev_p2_rui_call&&P2.at(34,3,2)(),run:()=>{
 const truth={t:t(`告诉他沉船那一夜的真相`,`Tell him the truth about the night of the wreck`,`Contar-lhe a verdade sobre a noite do naufrágio`),req:P2.letters(8),fx:()=>{S.flags.p2_ruiKnows=1;stat('saud',3)},next:()=>say(t(`太会背东西`,`Too good at carrying`,`Bons de mais a carregar`),t(`你讲外公坚持出海，讲厨子十六岁的儿子被缆绳缠住，讲若泽放开舵跳下去。鲁伊很久没说话。“外公骂了他三十年……”他躺下来看着德州的天，“我们家的人太会背东西了。”`,`You tell him Grandpa insisted on going out, about the cook's sixteen-year-old boy caught in the rope, about José letting go of the wheel and jumping. Rui is quiet a long time. "And Grandpa cursed him for thirty years…" He lies back under the Texas sky. "Our family's too good at carrying things."`,`Contas que o avô insistiu em sair, do filho de dezasseis anos do cozinheiro preso no cabo, do José a largar o leme e a saltar. O Rui fica muito tempo calado. «E o avô a amaldiçoá-lo trinta anos…» Deita-se debaixo do céu do Texas. «A nossa família é boa de mais a carregar coisas.»`))};
 if(S.flags.p2_rui!=='coming')return {title:t(`视频里的阿尔法马`,`Alfama on video`,`Alfama em vídeo`),meta:P2.M.rui,text:[
  t(`鲁伊举着手机走上阿尔法马的台阶，一共九十二级。“妈现在一天只下一次楼。”他喘着气，“你那边是什么样？”`,`Rui climbs the Alfama steps with the phone held up, ninety-two of them. "Mom only goes down once a day now." He's out of breath. "What's it like there?"`,`O Rui sobe as escadinhas de Alfama de telemóvel no ar, noventa e duas. «A mãe agora só desce uma vez por dia.» Está sem fôlego. «Como é isso aí?»`),
  t(`到了顶上，他把镜头转过来，对着家里的窗户。妈妈坐在窗边剥豆子，看见镜头，把头发拢了拢，像要见客人。“你弟弟说你那边的天很大，”她说，“比我们这条街大吗？”`,`At the top he turns the camera to the window at home. Mom is shelling beans by it; seeing the lens, she smooths her hair as if company's coming. "Your brother says the sky's very big over there," she says. "Bigger than our street?"`,`Lá em cima, vira a câmara para a janela de casa. A mãe está a debulhar feijão ao pé dela; ao ver a lente, compõe o cabelo como se viesse visita. «O teu irmão diz que aí o céu é muito grande», diz. «Maior que a nossa rua?»`)],choices:[
  {t:t(`把镜头对着店后的空地，给他看一整个日落`,`Point the camera at the lot and show him a whole sunset`,`Apontar a câmara para o terreno e mostrar-lhe um pôr do sol inteiro`),fx:()=>{stat('saud',3);S.lusoThisWeek=true}},
  {t:t(`讲你这一年认识的人`,`Tell him about the people you've met this year`,`Falar-lhe das pessoas que conheceste este ano`),fx:()=>{stat('tex',1)}},
  truth]};
 return {title:t(`屋顶`,`The roof`,`O telhado`),meta:P2.M.rui,text:[
  t(`夜里你们爬上屋顶。主街的灯一盏一盏熄了，只剩水塔上那盏红灯。`,`At night you climb onto the roof. Main Street's lights go out one by one until there's only the red lamp on the water tower.`,`À noite sobem ao telhado. As luzes da rua principal apagam-se uma a uma até só restar a luz vermelha da torre da água.`),
  t(`“你走的那天，妈在门口站了一个小时，”鲁伊说，“跟泽走的时候一样。我们家的人就会站在门口。你走了，泽也走了。留下的那个，从来没人问他想不想走。”`,`"The day you left, Mom stood in the doorway an hour," Rui says. "Same as when Zé left. That's what our family does — stands in doorways. You left, Zé left. Nobody ever asks the one who stays if he wanted to go."`,`«No dia em que te foste, a mãe ficou uma hora à porta», diz o Rui. «Como quando o Zé se foi. É o que a nossa família faz — fica à porta. Tu foste, o Zé foi. Ninguém pergunta ao que fica se ele queria ir.»`)],choices:[
  truth,
  {t:t(`把若泽的信给他看`,`Show him José's letters`,`Mostrar-lhe as cartas do José`),req:P2.letters(5),fx:()=>{S.flags.p2_ruiLetters=1;stat('saud',2)},next:()=>say(t(`你照顾谁`,`Who do you look after`,`De quem cuidas tu`),t(`他一封一封读，读到“替我照顾他”，把信纸折了起来。“他让妈照顾外公，妈照顾了。然后轮到我照顾妈。”他把信还给你，“你照顾谁？”`,`He reads them one by one. At "look after him for me" he folds the page. "He asked Mom to look after Grandpa, and she did. Then it was my turn to look after Mom." He hands them back. "Who do you look after?"`,`Lê-as uma a uma. Em «cuida dele por mim», dobra a folha. «Pediu à mãe que cuidasse do avô, e ela cuidou. Depois foi a minha vez de cuidar da mãe.» Devolve-tas. «E tu cuidas de quem?»`))},
  {t:t(`“对不起，是我把家留给了你。”`,`"I'm sorry. I left home on your shoulders."`,`«Desculpa. Deixei a casa às tuas costas.»`),fx:()=>{stat('saud',2)},next:()=>say(t(`电视剧`,`Soap opera`,`Novela`),t(`他笑了一下：“别搞得像电视剧。”过了一会儿：“不过，谢谢你说出来。”`,`He snorts. "Don't make it a soap opera." Then, after a while: "But thanks for saying it."`,`Ri-se pelo nariz. «Não faças disto uma novela.» Passado um bocado: «Mas obrigado por dizeres.»`))},
  {t:t(`[魅力 45] 开个玩笑岔过去`,`[Charm 45] Crack a joke and change the subject`,`[Charme 45] Fazer uma piada e mudar de assunto`),req:CHARM_REQ(45),fx:()=>{stat('charme',1)},next:()=>say(t(`没说出来的`,`Unsaid`,`Por dizer`),t(`他跟着笑了。笑完，你们都没再说话。有些话在屋顶上没说出来，就带回了里斯本。`,`He laughs along. Afterwards neither of you says anything. Some things not said on a roof get carried back to Lisbon.`,`Ele ri-se contigo. Depois nenhum dos dois diz nada. Há coisas que não se dizem num telhado e acabam por voltar para Lisboa.`))}]};
}},

/* =============== A · Rui (4) =============== */
{id:'p2_rui_leave',when:()=>S.flags.p2_rui==='coming'&&!!S.flags.ev_p2_rui_arrive&&P2.at(34,7,0,0)(),run:()=>({title:t(`回程`,`Going back`,`O regresso`),meta:P2.M.rui,text:[
 t(`去奥斯汀机场的路上，鲁伊一直看着窗外的牧场。快到的时候他说：“露西娅她爸说开春牧场缺人。卡车司机说油田一小时三十块。”他没看你，“我要是也留下呢？”`,`All the way to the Austin airport Rui watches the ranchland go by. Near the end he says, "Lucía's dad says the ranch needs hands in spring. A trucker told me the oilfield pays thirty an hour." He doesn't look at you. "What if I stayed too?"`,`No caminho para o aeroporto de Austin, o Rui vai a ver os ranchos passar. Quase a chegar diz: «O pai da Lucía diz que na primavera o rancho precisa de gente. Um camionista disse-me que o petróleo paga trinta à hora.» Não olha para ti. «E se eu também ficasse?»`)],choices:[
 {t:t(`“先回去陪妈。明年，我们一起决定谁留下。”`,`"Go home to Mom first. Next year we decide together who stays."`,`«Primeiro volta para a mãe. Para o ano decidimos juntos quem fica.»`),fx:()=>{S.flags.p2_ruiFuture='next';stat('saud',2)},next:()=>say(t(`安检口`,`Security`,`Controlo de segurança`),t(`他点点头。安检口前他回头：“圣安东尼节，你要是真办，我想办法来。”`,`He nods. At security he turns. "If you really do that Santo António, I'll find a way."`,`Acena. No controlo de segurança volta-se. «Se fizeres mesmo esse Santo António, eu arranjo maneira de vir.»`))},
 {t:t(`“家里得有一个人。你比我会照顾她。”`,`"Someone has to be home. You're better at looking after her than me."`,`«Alguém tem de estar em casa. Tu tratas dela melhor do que eu.»`),fx:()=>{S.flags.p2_ruiFuture='home';stat('saud',4)},next:()=>say(t(`拥抱`,`A hug`,`Um abraço`),t(`“你也就会说这种话。”他抱了你一下，很用力，像小时候打架输了。`,`"Course you'd say that." He hugs you hard, like when he lost a fight as a kid.`,`«Claro que dizias isso.» Abraça-te com força, como quando perdia uma luta em miúdo.`))},
 {t:t(`[口碑 45] “这一年满了，来店里当我的合伙人。”`,`[Reputation 45] "When the year's up, come be my partner in the shop."`,`[Reputação 45] «Quando acabar o ano, vem ser meu sócio.»`),req:()=>S.rep>=45||NEED(t(`口碑 45`,`Reputation 45`,`Reputação 45`)),fx:()=>{S.flags.p2_ruiFuture='partner';stat('tex',1);log('请鲁伊明年来当合伙人','Asked Rui to be your partner next year','Convidaste o Rui para sócio no próximo ano')},next:()=>say(t(`不洗盘子`,`No dishes`,`Pratos não`),t(`他愣住了，然后笑得像个十五岁的孩子：“先说好，我不洗盘子。”`,`He stares, then grins like he's fifteen. "Deal. But I'm not washing dishes."`,`Fica parado e depois sorri como se tivesse quinze anos. «Combinado. Mas não lavo pratos.»`))},
 {t:t(`[德州味 40] 在加油站请他吃早餐卷饼，什么都不说`,`[Texanness 40] Buy him breakfast tacos at a gas station and say nothing`,`[Texanidade 40] Pagar-lhe tacos de pequeno-almoço numa bomba de gasolina e não dizer nada`),req:()=>S.stats.tex>=40||NEED(t(`德州味 40`,`Texanness 40`,`Texanidade 40`)),fx:()=>{S.flags.p2_ruiFuture='open';stat('tex',1)},next:()=>say(t(`太大了`,`Too big`,`Grande de mais`),t(`他吃了三个，说德州的东西都太大了。可你看得出来，他已经在心里量过这片天有多大。`,`He eats three and says everything in Texas is too big. But you can tell he's already measured this sky in his head.`,`Come três e diz que tudo no Texas é grande de mais. Mas percebes que já mediu este céu de cabeça.`))}]})},

/* =============== B · Travis (3) =============== */
{id:'p2_travis3',when:()=>!!S.flags.ev_p2_travis1&&P2.at(35,1,2)(),run:()=>({title:t(`十五岁那年`,`The year he was fifteen`,`Quando ele tinha quinze anos`),meta:t(`孤星酒吧 · 打烊后`,`The Lone Star · after closing`,`O Lone Star · depois de fechar`),text:[
 t(`特拉维斯一个人坐在吧台尽头，厄尔已经不给他倒了。他看见你，把一杯没动过的啤酒推过来。`,`Travis sits alone at the end of the bar; Earl has stopped serving him. He sees you and pushes over a beer he hasn't touched.`,`O Travis está sozinho ao fundo do balcão; o Earl já não lhe serve mais. Vê-te e empurra-te uma cerveja em que não tocou.`),
 t(`“我十五岁那年，我爸半夜把我叫起来，让我坐在罐车副驾驶上。凌晨两点，往东边的旧井里倒。他说：‘这就是生意，你迟早要学。’”他盯着杯子，“我学会了。你要去罐头厂，对吧？别一个人去，四楼的地板是烂的。这话我没说过。”`,`"When I was fifteen my dad got me up in the middle of the night and sat me in the cab of the tanker. Two a.m., dumping into the old well out east. He said, 'This is business. You'll have to learn it sooner or later.'" He stares into the glass. "I learned. You're going into that cannery, ain't you? Don't go alone. Fourth floor's rotten. I never said that."`,`«Quando eu tinha quinze anos, o meu pai acordou-me a meio da noite e sentou-me na cabine do camião-cisterna. Duas da manhã, a despejar no poço velho a nascente. Disse: "Isto é negócio. Mais cedo ou mais tarde tens de aprender."» Olha para o copo. «Aprendi. Vais à fábrica, não vais? Não vás sozinho. O quarto andar está podre. Eu não disse nada.»`)],choices:[
 {t:t(`“你可以第一个说出来。”`,`"You could be the first to say it out loud."`,`«Podias ser o primeiro a dizê-lo em voz alta.»`),req:()=>(S.flags.p2_tv||0)>=1||NEED(t(`在健身房或沟边帮过他`,`Helped him at the gym or the ditch`,`Ajudaste-o no ginásio ou na valeta`)),fx:()=>{P2.tv(1);S.flags.p2_travisAsked=1},next:()=>say(t(`一个理由`,`One reason`,`Uma razão`),t(`他停在门口：“说出来，我爸进监狱，我破产，这镇子少一半工作。你给我一个理由。”你给不出来。他走了，但这一次没有摔门。`,`He stops at the door. "I say it, my dad goes to prison, I go broke, this town loses half its jobs. Give me one reason." You can't. He leaves — but this time he doesn't slam the door.`,`Para à porta. «Se eu falar, o meu pai vai preso, eu vou à falência, a vila perde metade dos empregos. Dá-me uma razão.» Não consegues. Ele sai — mas desta vez não bate com a porta.`))},
 {t:t(`第二天把这番话告诉科琳`,`Pass it on to Colleen next morning`,`Contar isto à Colleen na manhã seguinte`),req:()=>rel('colleen').met||NEED(t(`认识科琳`,`Know Colleen`,`Conhecer a Colleen`)),fx:()=>{P2.tv(-1);addTrust('colleen',1);S.flags.p2_travisTold=1},next:()=>say(t(`往哪儿挖`,`Where to dig`,`Onde cavar`),t(`科琳听完，没记笔记。“醉话不算证据，”她说，“但能知道往哪儿挖。”`,`Colleen listens and doesn't take a single note. "Drunk talk isn't evidence," she says. "But it tells you where to dig."`,`A Colleen ouve e não escreve nada. «Conversa de bêbedo não é prova», diz. «Mas diz-te onde cavar.»`))},
 {t:t(`谢谢他提醒四楼的事`,`Thank him for the warning about the fourth floor`,`Agradecer-lhe o aviso sobre o quarto andar`),fx:()=>{S.flags.p2_floorWarn=1},next:()=>say(t(`手背`,`On your hand`,`Na mão`),t(`你回家把这句话写在手背上：四楼，烂的。`,`At home you write it on the back of your hand: fourth floor, rotten.`,`Em casa escreves nas costas da mão: quarto andar, podre.`))}]})},

/* =============== C · Earl (2) =============== */
{id:'p2_earl2',when:()=>!!S.flags.ev_p2_earl1&&P2.at(38,7,2,0)(),run:()=>({title:t(`出售`,`For sale`,`Vende-se`),meta:P2.M.earl,text:[
 t(`周日晚上，孤星酒吧门上挂了一块手写的牌子：“出售”。`,`Sunday night there's a hand-lettered sign on the Lone Star's door: FOR SALE.`,`Domingo à noite há uma tabuleta escrita à mão na porta do Lone Star: VENDE-SE.`),
 t(`“心脏，”厄尔说，“医生说我再站十四个小时，就躺下别起来了。乔琳要纳什维尔，不要这地方，我不怪她。奥斯汀来了个中介，开价三万，说买家要改成卡车司机宿舍。”名片上印着“孤星砂业”。“七千五，卖给一个留着点唱机的人。这个价，我只开到下个月。”`,`"Heart," Earl says. "Doc says I stand fourteen more hours a day, I lie down and don't get up. Jolene wants Nashville, not this place, and I don't blame her. Broker came up from Austin offering thirty grand — says the buyer wants a trucker bunkhouse." The card reads LONE STAR SAND. "Seventy-five hundred to somebody who keeps the jukebox. That price stands till next month."`,`«O coração», diz o Earl. «O médico diz que, se continuo catorze horas de pé, deito-me e não me levanto. A Jolene quer Nashville, não isto, e não a censuro. Veio um intermediário de Austin oferecer trinta mil — diz que o comprador quer uma camarata para camionistas.» O cartão diz LONE STAR SAND. «Sete mil e quinhentos a quem ficar com a jukebox. Esse preço vale até ao mês que vem.»`)],choices:[
 {t:t(`“别卖给特拉维斯。给我五个星期。”`,`"Don't sell to Travis. Give me five weeks."`,`«Não vendas ao Travis. Dá-me cinco semanas.»`),fx:()=>{S.flags.p2_earl='wait';addTrust('earl',1)}},
 {t:t(`去问乔琳到底怎么想`,`Ask Jolene what she really thinks`,`Perguntar à Jolene o que pensa mesmo`),req:()=>rel('jolene').met||NEED(t(`认识乔琳`,`Know Jolene`,`Conhecer a Jolene`)),fx:()=>{S.flags.p2_earl='jolene';addTrust('jolene',1)},next:()=>say(t(`后门`,`The back door`,`A porta das traseiras`),t(`乔琳在后门抽烟：“我爱这地方，就像爱我爷爷——我不想在这儿变成他。”她把烟踩灭，“可我也不想看它变成宿舍。”`,`Jolene is smoking out back. "I love this place like I love Grandpa — I just don't want to turn into him in here." She grinds out the cigarette. "But I don't want to watch it turn into a bunkhouse either."`,`A Jolene fuma lá atrás. «Gosto deste sítio como gosto do avô — só não me quero transformar nele aqui dentro.» Esmaga o cigarro. «Mas também não quero vê-lo virar camarata.»`))},
 {t:t(`“你辛苦了一辈子，卖给出价最高的人。”`,`"You've worked your whole life. Sell to the highest bidder."`,`«Trabalhaste a vida toda. Vende a quem der mais.»`),fx:()=>{S.flags.p2_earl='free'},next:()=>say(t(`替别人着想`,`Thinking of others`,`A pensar nos outros`),t(`厄尔点点头，没看你。“若泽也会这么说。他总替别人着想，替错了地方。”`,`Earl nods without looking at you. "José would've said that. Always thinking of other folks, and always in the wrong place."`,`O Earl acena sem olhar para ti. «O José dizia o mesmo. Sempre a pensar nos outros, e sempre no sítio errado.»`))}]})},

/* =============== F · ranch (3) =============== */
{id:'p2_ranch3',when:()=>!!S.flags.ev_p2_ranch2&&P2.at(40,6,1)(),run:()=>{
 if(S.flags.p2_beto==='option'&&S.flags.c4_vote==='blocked')S.flags.p2_beto='held';
 const held=S.flags.p2_beto==='held';
 const T=[t(`四月的第一场大雨下了一整夜。早上，雷耶斯牧场的蓄水池满了，蓝帽子花从路边一直开到栅栏。`,`The first big April rain falls all night. By morning the Reyes stock tank is full and bluebonnets run from the road to the fence.`,`A primeira grande chuva de abril cai a noite inteira. De manhã, o bebedouro dos Reyes está cheio e há tremoceiros-azuis desde a estrada até à cerca.`)];
 T.push(held?t(`贝托开着皮卡来了，后斗里是半扇牛。“从今往后，牛肉按自家价给你。若泽那份，你那份。”`,`Beto pulls up with half a steer in the bed of the truck. "From now on you get beef at family price. José's share, and yours."`,`O Beto chega com meia rês na caixa da carrinha. «De hoje em diante, a carne é a preço de família. A parte do José, e a tua.»`)
  :t(`那份优先购买权还压在贝托的抽屉里。改划的消息一出，中介又打电话来了。`,`That option is still sitting in Beto's drawer. The moment the rezoning news broke, the broker started calling again.`,`O tal direito de preferência continua na gaveta do Beto. Mal saiu a notícia da requalificação, o intermediário voltou a ligar.`));
 const ch=held?[
  {t:t(`收下，请他留下来吃饭`,`Accept, and ask him to stay for dinner`,`Aceitar e convidá-lo para jantar`),fx:()=>{P2.beefPerk();addLike('beto',1)}},
  {t:t(`告诉他东边旧井和罐车的事`,`Tell him about the old well out east and the tanker`,`Contar-lhe do poço velho a nascente e do camião-cisterna`),req:P2.letters(9),fx:()=>{P2.beefPerk();addTrust('beto',2);S.flags.p2_betoKnows=1},next:()=>say(t(`雨里`,`In the rain`,`À chuva`),t(`贝托听完，摘下帽子，在雨里站了很久。“我一直以为是我没看好它们。”`,`Beto hears it out, takes off his hat and stands in the rain a long time. "All these years I thought I just didn't look after 'em right."`,`O Beto ouve tudo, tira o chapéu e fica muito tempo à chuva. «Estes anos todos pensei que tinha sido eu a não tratar bem delas.»`))}]
 :[
  {t:t(`[$1,500] 替他把优先购买权买回来`,`[$1,500] Buy back the option for him`,`[$1.500] Resgatar-lhe o direito de preferência`),req:MONEY(1500),fx:()=>{S.cash-=1500;S.flags.p2_beto='held';P2.beefPerk();addTrust('beto',2)},next:()=>say(t(`火里`,`Into the fire`,`Para o fogo`),t(`贝托把撕碎的合同扔进火里：“欠你的。我记着。”`,`Beto drops the torn contract into the fire. "I owe you. I won't forget."`,`O Beto atira o contrato rasgado para o lume. «Fico a dever-te. Não me esqueço.»`))},
  {t:t(`请格蕾丝看看合同`,`Ask Grace to look at the contract`,`Pedir à Grace que veja o contrato`),req:()=>rel('grace').trust>=3||NEED(t(`格蕾丝信任 3`,`Grace's trust 3`,`Confiança da Grace 3`)),fx:()=>{S.flags.p2_beto='held';P2.beefPerk();addTrust('grace',1);addTrust('beto',1)},next:()=>say(t(`第十一条`,`Clause eleven`,`Cláusula onze`),t(`格蕾丝在第十一条下面画了一道线：“中介没在期限内付定金。这份东西，作废。”`,`Grace underlines clause eleven. "The broker never paid the deposit on time. This thing is void."`,`A Grace sublinha a cláusula onze. «O intermediário não pagou o sinal a tempo. Isto não vale nada.»`))},
  {t:t(`你帮不上`,`There's nothing you can do`,`Não há nada que possas fazer`),next:()=>say(t(`暂时`,`For now`,`Por agora`),t(`贝托说：“没事，地还在我名下。”你们都知道，那只是暂时的。`,`Beto says, "It's fine. Land's still in my name." You both know that's only for now.`,`O Beto diz: «Não faz mal. A terra ainda está em meu nome.» Sabem os dois que é só por agora.`))}];
 return {title:t(`春雨`,`Spring rain`,`Chuva de primavera`),meta:P2.M.ranch,text:T,choices:ch};
}},

/* =============== B · Travis (4): the fork =============== */
{id:'p2_travis4',when:()=>!!S.flags.ev_p2_travis1&&P2.at(41,2,2)(),run:()=>{const tv=S.flags.p2_tv||0;
 if(S.flags.travisDeal==='deal')return {title:t(`交易之后`,`After the deal`,`Depois do negócio`),meta:P2.M.travis,text:[
  t(`推土机在罐头厂地块上推出了一条路。特拉维斯来店里，第一次点了沙丁鱼。“清理？”他笑，“铺一层碎石，围一圈铁丝网，州里的人看不出来。钱你拿了，这事就跟你没关系了。”`,`The bulldozers have cut a road across the cannery lot. Travis comes into the shop and, for the first time, orders sardines. "Cleanup?" He grins. "A layer of gravel, a ring of wire fence. The state boys won't know the difference. You took the money. It's none of your business now."`,`Os bulldozers abriram um caminho no terreno da fábrica. O Travis entra no restaurante e, pela primeira vez, pede sardinhas. «Limpeza?» Sorri. «Uma camada de gravilha, uma cerca de arame. Os do estado não dão pela diferença. Ficaste com o dinheiro. Já não é assunto teu.»`),
  t(`他的手指在杯沿上敲个不停。你想起健身房里那个躺着、等人来数数的人。`,`His fingers drum the rim of the glass. You think of the man lying under the bar at the gym, waiting for someone to count.`,`Os dedos dele tamborilam no rebordo do copo. Lembras-te do homem deitado debaixo da barra no ginásio, à espera que alguém contasse.`)],choices:[
  {t:t(`“你爸八十岁了还在数。你想数到什么时候？”`,`"Your dad's eighty and still counting. How long are you going to?"`,`«O teu pai tem oitenta anos e ainda conta. Até quando vais contar tu?»`),req:()=>tv>=2||rel('roz').trust>=6||NEED(t(`见过他的另一面，或罗兹信任 6`,`Have seen his other side, or Roz's trust 6`,`Ter visto o outro lado dele, ou confiança da Roz 6`)),fx:()=>{S.flags.p2_travis='turned';addTrust('roz',1);addTrust('travis',2);S.rep+=2;log('特拉维斯答应真正清理罐头厂','Travis agrees to a real cleanup','O Travis aceita fazer uma limpeza a sério')},next:()=>say(t(`真打井，真化验`,`Real wells, real tests`,`Poços a sério, análises a sério`),t(`他很久没说话。第二周，罗兹在奥斯汀的公司收到一份合同：罐头厂地下水治理，真打井，真化验。签字的是特拉维斯本人，不是他的会计。`,`He's silent a long time. The next week Roz's firm in Austin receives a contract: groundwater remediation at the cannery, real wells, real lab work. Signed by Travis himself, not his accountant.`,`Fica muito tempo calado. Na semana seguinte, a empresa da Roz em Austin recebe um contrato: descontaminação das águas da fábrica, poços a sério, análises a sério. Assinado pelo próprio Travis, não pelo contabilista.`))},
  {t:t(`[$3,000] 拿出一部分钱，作为清理基金的第一笔`,`[$3,000] Put part of the money back as the first payment into a cleanup fund`,`[$3.000] Devolver parte do dinheiro como primeira entrada para a limpeza`),req:MONEY(3000),fx:()=>{S.cash-=3000;S.flags.p2_travis='turned';S.rep+=3;addTrust('lucia',1);log('拿出 $3,000 做罐头厂清理基金','Put $3,000 into a cannery cleanup fund','Puseste $3.000 num fundo de limpeza da fábrica')},next:()=>say(t(`疯了`,`Crazy`,`Doido`),t(`他盯着支票：“你疯了。”“我舅舅也疯了。”三天后钻井车开进罐头厂，这次是来打监测井的。`,`He stares at the check. "You're crazy." "So was my uncle." Three days later a drill rig rolls into the cannery — this time to sink monitoring wells.`,`Ele fica a olhar para o cheque. «Estás doido.» «O meu tio também estava.» Três dias depois entra uma sonda na fábrica — desta vez para abrir poços de monitorização.`))},
  {t:t(`“那就照你当年学会的那样干。我也学会了。”`,`"Then do it the way you learned. I've learned too."`,`«Então faz como aprendeste. Eu também aprendi.»`),fx:()=>{S.flags.p2_travis='bad';stat('tex',2);stat('saud',-2);addTrust('lucia',-1)},next:()=>say(t(`铁盒`,`The tin`,`A lata`),t(`他点点头，像松了一口气。走的时候他多付了五十块小费。你把那五十块放进若泽的铁盒，盒盖怎么也合不上。`,`He nods, like he's relieved. On the way out he leaves a fifty-dollar tip. You put the fifty in José's tin, and the lid won't close.`,`Acena, como se estivesse aliviado. À saída deixa cinquenta dólares de gorjeta. Metes os cinquenta na lata do José, e a tampa não fecha.`))}]};
 const v=S.flags.c4_vote==='blocked';
 return {title:t(`借来的车`,`A borrowed car`,`Um carro emprestado`),meta:P2.M.travis,text:[
  v?t(`改划被否决以后，休斯敦的电话从一天七次变成了一天二十次。特拉维斯卖了他的黑色皮卡，开着一辆借来的旧车来店里。`,`Since the rezoning was voted down, Houston calls twenty times a day instead of seven. Travis has sold the black pickup; he comes to the shop in a borrowed old sedan.`,`Desde que a requalificação foi chumbada, Houston liga vinte vezes por dia em vez de sete. O Travis vendeu a carrinha preta; chega ao restaurante num carro velho emprestado.`)
   :t(`改划通过了，可环境评估把开工推到了明年，休斯敦的人等不了。特拉维斯卖了他的黑色皮卡，开着一辆借来的旧车来店里。`,`The rezoning passed, but the environmental review pushed the work back a year, and Houston won't wait. Travis has sold the black pickup; he comes to the shop in a borrowed old sedan.`,`A requalificação passou, mas a avaliação ambiental empurrou a obra para o ano que vem, e Houston não espera. O Travis vendeu a carrinha preta; chega ao restaurante num carro velho emprestado.`),
  t(`“别误会，我不是来求你的。”他坐下，“我只是饿了。”`,`"Don't get ideas. I'm not here to beg." He sits. "I'm just hungry."`,`«Não penses coisas. Não vim pedir nada.» Senta-se. «Só tenho fome.»`)],choices:[
  {t:t(`给他上一盘沙丁鱼，不收钱`,`Serve him sardines on the house`,`Servir-lhe sardinhas por conta da casa`),fx:()=>{S.flags.p2_travis=tv>=2?'humbled':'bitter';if(tv>=2)addTrust('travis',1)},next:()=>say(t(`一盘鱼`,`A plate of fish`,`Um prato de peixe`),tv>=2?t(`他吃完，用餐巾擦了很久的手：“州里的人约我谈话。我打算把罐车的事说出来——我十五岁那年的事。”`,`He finishes and wipes his hands on the napkin a long time. "The state wants to interview me. I'm going to tell them about the tanker. About when I was fifteen."`,`Acaba e limpa as mãos ao guardanapo muito tempo. «O estado quer falar comigo. Vou contar do camião-cisterna. De quando eu tinha quinze anos.»`):t(`他吃完，丢下二十块：“别以为一盘鱼就能让我们扯平。”`,`He finishes and drops a twenty. "Don't think a plate of fish makes us square."`,`Acaba e deixa vinte dólares. «Não penses que um prato de peixe nos põe quites.»`))},
  {t:t(`“我舅舅丢了工作，没丢名字。你还来得及。”`,`"My uncle lost his job, not his name. You've still got time."`,`«O meu tio perdeu o emprego, não o nome. Ainda vais a tempo.»`),req:P2.letters(9),fx:()=>{S.flags.p2_travis='humbled';addTrust('travis',2)},next:()=>say(t(`我会送他来`,`I'll drive him`,`Eu trago-o`),t(`他看着窗外那块空地：“我爸想来你店里，说他欠若泽一句话。”他停了一下，“我不会下车。但我会送他来。”`,`He looks out at the empty lot. "My dad wants to come here. Says he owes José a sentence." A pause. "I won't get out of the truck. But I'll drive him."`,`Olha para o terreno vazio. «O meu pai quer vir cá. Diz que deve uma frase ao José.» Uma pausa. «Eu não saio do carro. Mas trago-o.»`))},
  {t:t(`“这里不欢迎你。”`,`"You're not welcome here."`,`«Aqui não és bem-vindo.»`),fx:()=>{S.flags.p2_travis='bitter';addTrust('travis',-1)},next:()=>say(t(`椅子`,`The chair`,`A cadeira`),t(`他站起来，把椅子推回原位，推得很整齐。“若泽也这么说过。”`,`He stands and pushes the chair back in, very neatly. "José said that too."`,`Levanta-se e arruma a cadeira, muito direitinha. «O José também disse isso.»`))}]};
}},

/* =============== E · kids (3): Tommy =============== */
{id:'p2_kids3',when:()=>!!S.flags.ev_p2_kids1&&P2.at(41,5,2)(),run:()=>({title:t(`签约日`,`Signing day`,`Dia da assinatura`),meta:P2.M.kids,text:[
 t(`汤米把两张纸摆在你的柜台上：一张是俄克拉何马那所大学的半奖合同，一张是社区大学的报名表。`,`Tommy lays two sheets on your counter: the half-scholarship papers from the Oklahoma college, and a community college application.`,`O Tommy põe duas folhas no teu balcão: os papéis da meia bolsa da universidade de Oklahoma e uma inscrição na faculdade comunitária.`),
 ...(S.staff.includes('tommy')?[t(`他在你店里跑了大半年堂，现在端三个盘子绕十圈也不掉了。`,`He's run tables for you most of the year; these days he can do ten laps with three plates and drop none.`,`Serviu às tuas mesas quase o ano inteiro; agora dá dez voltas com três pratos sem deixar cair nenhum.`)]:[]),
 t(`“下周五前要签。我妈说：去。我妹说：别去。”他挠挠头，“我自己……我喜欢这儿，喜欢早上六点店里的味道。这算理由吗？”`,`"Got to sign by next Friday. Mom says go. My sister says don't." He scratches his head. "Me… I like it here. I like how the shop smells at six in the morning. Is that a reason?"`,`«Tenho de assinar até sexta. A minha mãe diz que vá. A minha irmã diz que não.» Coça a cabeça. «Eu… gosto disto. Gosto do cheiro do restaurante às seis da manhã. Isso é uma razão?»`)],choices:[
 {t:t(`“去。圣鲁伊斯会在这儿等你。”`,`"Go. San Luís will be here."`,`«Vai. San Luís fica cá à tua espera.»`),fx:()=>{S.flags.p2_tommy='college'},next:()=>say(t(`签字`,`Signed`,`Assinado`),t(`他签了字，签得很用力，把纸都划破了一点。`,`He signs, pressing so hard the pen tears the paper a little.`,`Assina com tanta força que a caneta rasga um bocadinho o papel.`))},
 {t:t(`[$1,000] 替他补上奖学金差的那一截`,`[$1,000] Cover the gap the scholarship leaves`,`[$1.000] Pagar o que a bolsa não cobre`),req:MONEY(1000),fx:()=>{S.cash-=1000;S.flags.p2_tommy='college';S.rep+=2},next:()=>say(t(`烟熏的`,`Smoke`,`Fumo`),t(`他盯着支票：“老板，我……”“四年后回来，给我当店长。”他哭了，说是烟熏的。`,`He stares at the check. "Boss, I…" "Come back in four years and run the place." He cries and says it's the smoke.`,`Fica a olhar para o cheque. «Patrão, eu…» «Volta daqui a quatro anos e gere isto.» Chora e diz que é do fumo.`))},
 {t:t(`[口碑 40] “留下来。这一年满了，店里给你一份全职，学费我出一半。”`,`[Reputation 40] "Stay. When the year's up there's a full-time job here, and I'll pay half your tuition."`,`[Reputação 40] «Fica. Quando acabar o ano tens cá um emprego a tempo inteiro, e pago metade das propinas.»`),req:()=>S.rep>=40||NEED(t(`口碑 40`,`Reputation 40`,`Reputação 40`)),fx:()=>{S.flags.p2_tommy='stay';S.flags.p2_tommyJob=1},next:()=>say(t(`纸飞机`,`Paper plane`,`Avião de papel`),t(`他把俄克拉何马的合同折成一架纸飞机，没扔，放进了口袋。“万一呢，”他说。`,`He folds the Oklahoma papers into a paper plane — and doesn't throw it. Puts it in his pocket. "Just in case," he says.`,`Dobra os papéis de Oklahoma num avião de papel — e não o atira. Guarda-o no bolso. «Para o caso de», diz.`))},
 {t:t(`“这算理由。但你得自己说出来，对你妈说。”`,`"It's a reason. But you have to say it yourself — to your mom."`,`«É uma razão. Mas tens de a dizer tu — à tua mãe.»`),fx:()=>{S.flags.p2_tommy='stay'},next:()=>say(t(`像样一点`,`Do it properly`,`Como deve ser`),t(`第二天他来上班，眼睛红红的。“我留下，”他说，“我妈说，那就留得像样一点。”`,`Next day he comes in with red eyes. "I'm staying," he says. "Mom says, then stay properly."`,`No dia seguinte chega com os olhos vermelhos. «Fico», diz. «A minha mãe diz que então fique como deve ser.»`))}]})},

/* =============== C · Earl (3) =============== */
{id:'p2_earl3',when:()=>!!S.flags.ev_p2_earl2&&P2.at(43,1,2)(),run:()=>{
 const own=k=>{S.flags.p2_saloon=k;log('孤星酒吧有了新主人','The Lone Star has a new owner','O Lone Star tem novo dono')};
 return {title:t(`七千五`,`Seventy-five hundred`,`Sete mil e quinhentos`),meta:P2.M.earl,text:[
  t(`中介又来了，这次开价三万五。厄尔把名片撕成两半，又拼起来，又撕了。“你想好了没有，孩子？”`,`The broker's back, offering thirty-five now. Earl tears the card in half, fits it back together, tears it again. "You made up your mind, son?"`,`O intermediário voltou, agora com trinta e cinco mil. O Earl rasga o cartão ao meio, junta-o, volta a rasgá-lo. «Já te decidiste, rapaz?»`),
  ...(S.flags.travisDeal==='deal'?[t(`你账上那笔钱是特拉维斯付的。用他的钱买他想要的东西——厄尔说，这叫德州式的公道。`,`The money in your account came from Travis. Using his money to buy the thing he wants — Earl calls that Texas justice.`,`O dinheiro na tua conta veio do Travis. Usar o dinheiro dele para comprar o que ele quer — o Earl chama a isso justiça texana.`)]:[])],choices:[
  {t:t(`[$7,500] 买下来`,`[$7,500] Buy it`,`[$7.500] Comprar`),req:MONEY(7500),fx:()=>{S.cash-=7500;own('bought');S.rep+=4;addTrust('earl',2)},next:()=>say(t(`钥匙`,`The keys`,`As chaves`),t(`厄尔把钥匙放在你手心，压了很久才松开。“点唱机里那首老歌，每天至少放一遍。”以后你可以去「孤星酒吧的账房」对账收钱。`,`Earl lays the keys in your palm and holds them there a long time before letting go. "That old song on the jukebox — once a day, minimum." From now on you can do the books at the Lone Star back office.`,`O Earl põe-te as chaves na mão e segura-as muito tempo antes de largar. «Aquela canção velha da jukebox — uma vez por dia, no mínimo.» A partir de agora podes fazer as contas no escritório do Lone Star.`))},
  {t:t(`[$3,750] 和乔琳一人一半`,`[$3,750] Go halves with Jolene`,`[$3.750] A meias com a Jolene`),req:()=>S.cash<3750?t(`钱不够`,`Not enough money`,`Não tens dinheiro`):rel('jolene').trust>=4||NEED(t(`乔琳信任 4`,`Jolene's trust 4`,`Confiança da Jolene 4`)),fx:()=>{S.cash-=3750;own('half');addTrust('jolene',2);addTrust('earl',1)},next:()=>say(t(`合同`,`The contract`,`O contrato`),t(`乔琳签名签得像在签专辑。“纳什维尔又不会跑。周一到周三我去录音，周四到周日我在这儿。”`,`Jolene signs like she's autographing an album. "Nashville ain't going anywhere. Monday to Wednesday I record; Thursday to Sunday I'm here."`,`A Jolene assina como quem autografa um disco. «Nashville não foge. De segunda a quarta gravo; de quinta a domingo estou aqui.»`))},
  {t:t(`说服乔琳接手，你帮她管账`,`Talk Jolene into taking it over; you'll do her books`,`Convencer a Jolene a ficar com o bar; tu tratas das contas`),req:()=>rel('jolene').trust>=6||(rel('jolene').like>=6&&charm()>=55)||NEED(t(`乔琳信任 6，或好感 6 且魅力 55`,`Jolene's trust 6, or affection 6 and charm 55`,`Confiança da Jolene 6, ou afeto 6 e charme 55`)),fx:()=>{own('jolene');addTrust('jolene',2);addLike('earl',1)},next:()=>say(t(`餐巾纸`,`The napkin`,`O guardanapo`),t(`厄尔用一块钱把酒吧卖给了孙女，合同写在一张餐巾纸上。乔琳把餐巾纸裱了起来。`,`Earl sells the bar to his granddaughter for a dollar, contract written on a napkin. Jolene has the napkin framed.`,`O Earl vende o bar à neta por um dólar, com o contrato escrito num guardanapo. A Jolene manda emoldurar o guardanapo.`))},
  {t:t(`[$1,500] 发动全镇入股`,`[$1,500] Get the whole town to buy shares`,`[$1.500] Pôr a vila inteira a comprar ações`),req:()=>S.cash<1500?t(`钱不够`,`Not enough money`,`Não tens dinheiro`):S.rep>=50||NEED(t(`口碑 50`,`Reputation 50`,`Reputação 50`)),fx:()=>{S.cash-=1500;own('coop');S.rep+=3;addTrust('earl',1);addTrust('albertina',1)},next:()=>say(t(`股东名单`,`The shareholders`,`Os acionistas`),t(`七十五个人，每人一百块：老乡会、乐队、老兵会。名单贴在吧台后面，第一行是厄尔，第二行是若泽——你替他买了一股。`,`Seventy-five people, a hundred dollars each: the Azorean club, the band, the VFW. The list goes up behind the bar. First line, Earl. Second line, José — you bought him a share.`,`Setenta e cinco pessoas, cem dólares cada: o clube açoriano, a banda, os veteranos. A lista fica atrás do balcão. Primeira linha, o Earl. Segunda, o José — compraste-lhe uma ação.`))},
  {t:t(`让他卖给出价最高的人`,`Let him sell to the highest bidder`,`Deixá-lo vender a quem der mais`),fx:()=>{own('travis');stat('saud',2)},next:()=>say(t(`坦普尔`,`Temple`,`Temple`),t(`合同签了。厄尔说他要搬去坦普尔，住在女儿家附近。出门时他没回头看那块招牌。`,`It's signed. Earl says he'll move to Temple, near his daughter. Walking out, he doesn't look back at the sign.`,`Está assinado. O Earl diz que vai para Temple, perto da filha. Ao sair, não olha para a tabuleta.`))}]};
}},

/* =============== D · Albertina (3): eighty =============== */
{id:'p2_alb3',when:()=>!!S.flags.ev_p2_alb2&&P2.at(44,7,1,0)(),run:()=>{const src=S.flags.p2_songSrc||'net';S.flags.p2_alb80=src;
 const T=[t(`阿尔贝蒂娜穿了一条蓝裙子，九位老太太戴着一样的珍珠耳环，席尔瓦先生打了领结。蛋糕上插着一个“8”和一个“0”，“0”是你用蛋挞拼的。`,`Albertina wears a blue dress, the nine old ladies the same pearl earrings, Mr. Silva a bow tie. On the cake stand an 8 and a 0; you made the 0 out of custard tarts.`,`A Albertina veste um vestido azul, as nove velhotas os mesmos brincos de pérola, o senhor Silva um laço. No bolo há um 8 e um 0; o 0 fizeste-o tu com pastéis de nata.`),
  {lisbon:t(`你用店里的音响放出里斯本那段录音。第一句出来，阿尔贝蒂娜就放下了叉子。`,`You play the Lisbon recording on the shop speakers. At the first line Albertina puts down her fork.`,`Pões a gravação de Lisboa nas colunas do restaurante. Ao primeiro verso, a Albertina pousa o garfo.`),austin:t(`奥斯汀的老板站到桌子中间，摘下帽子开始唱。`,`The man from the Austin market stands in the middle of the tables, takes off his cap and begins.`,`O homem do mercado de Austin põe-se no meio das mesas, tira o boné e começa a cantar.`),kyle:t(`凯尔放下唱针。裂缝“咔”的一声，一个六十年前的声音从大西洋那头唱过来。`,`Kyle lowers the needle. The crack clicks, and a voice from sixty years ago sings across the Atlantic.`,`O Kyle pousa a agulha. A racha estala, e uma voz de há sessenta anos canta do outro lado do Atlântico.`),net:t(`你放了那段巴西录音。老太太们礼貌地听着。阿尔贝蒂娜拍拍你的手：“不是这个，孩子。没关系。”`,`You play the Brazilian recording. The ladies listen politely. Albertina pats your hand. "That's not it, child. Never mind."`,`Pões a gravação brasileira. As senhoras ouvem com educação. A Albertina dá-te uma palmadinha na mão. «Não é essa, filho. Não faz mal.»`)}[src]];
 if(src!=='net')T.push(t(`唱到第二段，她跟着唱了起来，用十二岁的声音。九位老太太一个接一个跟上。席尔瓦先生果然哭了。`,`At the second verse she joins in, in a twelve-year-old's voice. One by one the nine ladies follow. Mr. Silva, as promised, cries.`,`Na segunda quadra junta-se, com voz de doze anos. Uma a uma, as nove senhoras seguem-na. O senhor Silva, como prometido, chora.`));
 const end=()=>{addTrust('albertina',1);S.rep+=2;if(src!=='net')P2.fishPerk()};
 const tail=t(`散场时，席尔瓦先生的孙子塞给你一张名片：他在加尔维斯顿有条渔船。“奶奶们说了，你的沙丁鱼以后从我这儿进。”`,`As people leave, Mr. Silva's grandson presses a card on you: he runs a fishing boat out of Galveston. "The grandmas have spoken. Your sardines come from me now."`,`À saída, o neto do senhor Silva dá-te um cartão: tem um barco de pesca em Galveston. «As avós já decidiram. As tuas sardinhas passam a vir de mim.»`);
 const after=x=>()=>say(t(`八十岁`,`Eighty`,`Oitenta anos`),src!=='net'?[x,tail]:[x]);
 return {title:t(`八十岁`,`Eighty`,`Oitenta anos`),meta:S.flags.p2_party?t(`若泽烧烤店`,`Zé's Churrasco`,`Churrasqueira do Zé`):t(`教堂地下室`,`The church basement`,`A cave da igreja`),text:T,choices:[
  {t:t(`请她跳一支岛上的舞`,`Ask her for an island dance`,`Convidá-la para uma moda das ilhas`),req:()=>charm()>=45||S.stats.saud>=50||NEED(t(`魅力 45 或乡愁 50`,`Charm 45 or Homesickness 50`,`Charme 45 ou Saudade 50`)),fx:()=>{end();addLike('albertina',2)},next:after(t(`她教你脚怎么踩，像踩甲板。转到第三圈，她说：“我丈夫也是这么笨的。”`,`She shows you where to put your feet, like on a ship's deck. On the third turn she says, "My husband was just as clumsy."`,`Ensina-te onde pôr os pés, como num convés. À terceira volta diz: «O meu marido era tão desajeitado como tu.»`))},
  {t:t(`送她那艘船的大照片，托科琳从报社档案里找的`,`Give her a big print of the ship, dug out of the newspaper archive by Colleen`,`Dar-lhe uma fotografia grande do navio, que a Colleen encontrou no arquivo do jornal`),req:()=>rel('colleen').met||NEED(t(`认识科琳`,`Know Colleen`,`Conhecer a Colleen`)),fx:()=>{end();addTrust('albertina',1);addLike('colleen',1)},next:after(t(`她用指尖找了很久，在栏杆边找到一个小小的白头巾：“这个是我。”`,`She searches with her fingertip a long time and finds a tiny white headscarf at the rail. "That's me."`,`Procura muito tempo com a ponta do dedo e encontra um lencinho branco junto à amurada. «Esta sou eu.»`))},
  {t:t(`安安静静地坐在她旁边`,`Sit quietly beside her`,`Ficar sentado em silêncio ao lado dela`),fx:()=>{end();stat('saud',3);S.lusoThisWeek=true},next:after(t(`她握着你的手，一直没松开。歌停了很久，她还在轻轻地打拍子。`,`She holds your hand and doesn't let go. Long after the song stops she's still tapping the beat.`,`Segura-te a mão e não a larga. Muito depois de a canção acabar, ainda marca o compasso.`))}]};
}},

/* =============== D · Albertina (4): the viola =============== */
{id:'p2_alb4',when:()=>!!S.flags.ev_p2_alb3&&P2.at(46,4,1,0)(),run:()=>{const fs=n=>{if(typeof c4_fs==='function')c4_fs(n)};
 return {title:t(`十二根弦`,`Twelve strings`,`Doze cordas`),meta:P2.M.alb,text:[
 t(`生日过后第十天，阿尔贝蒂娜抱着一个裹在床单里的长盒子走进店里。里面是一把亚速尔的十二弦吉他，琴腹上镶着两颗贝壳做的心。`,`Ten days after the birthday Albertina walks in carrying a long case wrapped in a bedsheet. Inside is an Azorean twelve-string guitar, two hearts of shell inlaid on its belly.`,`Dez dias depois do aniversário, a Albertina entra com uma caixa comprida embrulhada num lençol. Lá dentro está uma viola da terra, com dois corações de madrepérola embutidos no tampo.`),
 t(`“我丈夫的。1958 年，船上只准每人带一个箱子，他把衣服全扔了，带了这个。”她把琴放在柜台上，“十一年没人弹了。圣安东尼节，我想让它走在游行里。别让它跟我一起进土里。”`,`"My husband's. In '58 they let each of us bring one trunk. He threw out all his clothes and brought this." She lays it on the counter. "Nobody's played it in eleven years. At the Santo António I want it in the parade. Don't let it go into the ground with me."`,`«Era do meu marido. Em 58 só deixavam levar uma mala a cada um. Ele deitou fora a roupa toda e trouxe isto.» Pousa-a no balcão. «Há onze anos que ninguém lhe toca. No Santo António quero-a no desfile. Não a deixes ir para a terra comigo.»`),
 t(`她又从包里拿出一张折了四折的纸：一份没写完的家谱，最后一行是她自己的名字，后面空着。`,`From her bag she also takes a sheet folded in four: an unfinished family tree. The last line is her own name, with nothing after it.`,`Da mala tira ainda uma folha dobrada em quatro: uma árvore genealógica por acabar. A última linha é o nome dela, e depois nada.`)],choices:[
 {t:t(`请凯尔给琴换弦，游行时由他来弹`,`Have Kyle restring it and play it in the parade`,`Pedir ao Kyle que lhe mude as cordas e a toque no desfile`),req:()=>rel('kyle').met||NEED(t(`认识凯尔`,`Know Kyle`,`Conhecer o Kyle`)),fx:()=>{S.flags.p2_viola='kyle';addLike('kyle',1);addTrust('albertina',1);fs(1)},next:()=>say(t(`第一个和弦`,`First chord`,`O primeiro acorde`),t(`凯尔调了一个晚上的弦。第一个和弦响起来的时候，他抬头说：“这东西比我的钢棒吉他还会哭。”阿尔贝蒂娜坐在后排，没擦眼泪。`,`Kyle spends a whole evening tuning it. When the first chord rings he looks up. "This thing cries better than my steel guitar." Albertina, in the back row, doesn't wipe her eyes.`,`O Kyle passa a noite inteira a afiná-la. Quando soa o primeiro acorde, levanta a cabeça. «Isto chora melhor que a minha steel guitar.» A Albertina, na última fila, não limpa os olhos.`))},
 {t:t(`[乡愁 50] 自己学，游行时你来弹那首《查马里塔》`,`[Homesickness 50] Learn it yourself and play the chamarrita in the parade`,`[Saudade 50] Aprender tu e tocar a chamarrita no desfile`),req:()=>S.stats.saud>=50||NEED(t(`乡愁 50`,`Homesickness 50`,`Saudade 50`)),fx:()=>{S.flags.p2_viola='you';addLike('albertina',2);S.lusoThisWeek=true;fs(1)},next:()=>say(t(`十二根弦`,`Twelve strings`,`Doze cordas`),t(`十二根弦，你的手指每晚都被勒出血印。第五个晚上，你终于弹完了第二段。楼下有人敲了敲后门——是阿尔贝蒂娜，她一直站在外面听。`,`Twelve strings; every night they cut grooves in your fingertips. On the fifth night you finally get through the second verse. Someone knocks at the back door — Albertina, who's been standing outside listening.`,`Doze cordas; todas as noites te marcam os dedos. À quinta noite chegas finalmente ao fim da segunda quadra. Batem à porta das traseiras — é a Albertina, que esteve lá fora a ouvir.`))},
 {t:t(`帮她把家谱写完，请科琳登在报上`,`Help her finish the family tree and have Colleen print it`,`Ajudá-la a acabar a árvore e pedir à Colleen que a publique`),req:()=>rel('colleen').trust>=3||NEED(t(`科琳信任 3`,`Colleen's trust 3`,`Confiança da Colleen 3`)),fx:()=>{S.flags.p2_viola='paper';addTrust('albertina',2);addTrust('colleen',1);S.rep+=2},next:()=>say(t(`第三版`,`Page three`,`Página três`),t(`《号角报》第三版登了一整页：法亚尔岛、一条白船、四十七个名字，和一把十二弦吉他。第二天，休斯敦、圣何塞、新贝德福德有三个陌生人打来电话：“我们好像是亲戚。”`,`Page three of the Herald runs it full-page: Faial, a white ship, forty-seven names and a twelve-string guitar. The next day three strangers call from Houston, San Jose and New Bedford. "We think we're family."`,`A página três do jornal sai inteira: o Faial, um navio branco, quarenta e sete nomes e uma viola da terra. No dia seguinte ligam três desconhecidos de Houston, San José e New Bedford. «Achamos que somos família.»`))},
 {t:t(`“这太贵重了，您留着吧。”`,`"This is too precious. You keep it."`,`«Isto é valioso de mais. Guarde-a a senhora.»`),fx:()=>{S.flags.p2_viola='kept'},next:()=>say(t(`床单`,`The bedsheet`,`O lençol`),t(`她把琴重新裹进床单，裹得很慢。“若泽也这么说过，”她说，“你们家的人，就是不肯收下东西。”`,`She wraps the guitar back in the sheet, very slowly. "José said the same," she says. "You people never will accept a thing."`,`Volta a embrulhar a viola no lençol, muito devagar. «O José disse o mesmo», diz. «Vocês, os dessa família, nunca aceitam nada.»`))}]};
}},

/* =============== E · kids (4): Pastor Dale =============== */
{id:'p2_kids4',when:()=>!!S.flags.ev_p2_kids2&&P2.at(45,6,2)(),run:()=>{rel('dale').met=true;const hid=S.flags.p2_ldNight==='hid';
 return {title:t(`那条路`,`That road`,`Aquela estrada`),meta:t(`戴尔牧师`,`Pastor Dale`,`Pastor Dale`),text:[
  t(`打烊后，戴尔牧师一个人坐在柜台边。他点了咖啡，一口没喝。`,`After closing, Pastor Dale sits alone at the counter. He orders coffee and doesn't drink it.`,`Depois de fechar, o Pastor Dale está sozinho ao balcão. Pede um café e não lhe toca.`),
  hid?t(`“那天夜里你没给我打电话，”他说，“我开着车在主街上转到天亮。”`,`"That night you didn't call me," he says. "I drove up and down Main Street till sunrise."`,`«Naquela noite não me ligaste», diz. «Andei de carro pela rua principal até nascer o sol.»`):t(`“那天夜里，谢谢你，”他说，“我一直没说。”`,`"Thank you for that night," he says. "I never said."`,`«Obrigado por aquela noite», diz. «Nunca te disse.»`),
  t(`“奥斯汀在 35 号州际公路往南一个小时。1989 年，我弟弟就死在这条路上。”他转着杯子，“我不是怕他画房子。我是怕他上了那条路，就再也不回来。”`,`"Austin's an hour south down I-35. In 1989 my brother died on that road." He turns the cup. "I'm not afraid of him drawing houses. I'm afraid he'll get on that road and never come back."`,`«Austin fica a uma hora para sul pela I-35. Em 1989 o meu irmão morreu nessa estrada.» Roda a chávena. «Não tenho medo que ele desenhe casas. Tenho medo que meta por aquela estrada e não volte.»`)],choices:[
  {t:t(`讲若泽和外公：一个不肯低头的父亲，等了儿子二十八年`,`Tell him about José and Grandpa: a father who wouldn't bend, waiting twenty-eight years for a son`,`Falar-lhe do José e do avô: um pai que não se dobrava, à espera de um filho vinte e oito anos`),req:P2.letters(8),fx:()=>{S.flags.p2_ld='blessed';addTrust('dale',2);log('戴尔牧师祝福了小戴尔去奥斯汀','Pastor Dale blessed Little Dale\'s move to Austin','O Pastor Dale abençoou a ida do Dale Júnior para Austin')},next:()=>say(t(`画好一点`,`Draw it well`,`Desenha bem`),t(`牧师摘下眼镜擦了很久：“我不想当那个站在码头上的人。”第二天，小戴尔的速写本扉页上多了一行字，是他父亲的笔迹：“画好一点。”`,`The pastor takes off his glasses and polishes them a long time. "I don't want to be the man standing on the dock." Next day, on the first page of Little Dale's sketchbook, a line in his father's hand: "Draw it well."`,`O pastor tira os óculos e limpa-os muito tempo. «Não quero ser o homem parado no cais.» No dia seguinte, na primeira página do caderno do Dale Júnior, uma linha com a letra do pai: «Desenha bem.»`))},
  {t:t(`“那就您开车送他去。亲自走一遍那条路。”`,`"Then you drive him. Ride that road yourself."`,`«Então leve-o o senhor. Faça essa estrada consigo.»`),req:()=>rel('dale').trust>=4||NEED(t(`戴尔牧师信任 4`,`Pastor Dale's trust 4`,`Confiança do Pastor Dale 4`)),fx:()=>{S.flags.p2_ld='blessed';addTrust('dale',1)},next:()=>say(t(`八月`,`August`,`Agosto`),t(`牧师想了很久：“八月。我开车，他画路边的东西。”他终于喝了一口咖啡，“凉了。”`,`The pastor thinks a long while. "August. I'll drive; he can draw what goes by." He finally sips the coffee. "Cold."`,`O pastor pensa muito tempo. «Agosto. Eu conduzo; ele desenha o que passar.» Finalmente bebe um gole. «Está frio.»`))},
  {t:t(`“这是您和他之间的事。”`,`"That's between you and him."`,`«Isso é entre o senhor e ele.»`),fx:()=>{S.flags.p2_ld='alone';if(hid)addTrust('dale',-1)},next:()=>say(t(`灰狗巴士`,`The Greyhound`,`O autocarro`),t(`他点点头，付了咖啡钱。八月，小戴尔一个人坐灰狗巴士去了奥斯汀。`,`He nods and pays for the coffee. In August, Little Dale takes the Greyhound to Austin alone.`,`Acena e paga o café. Em agosto, o Dale Júnior apanha sozinho o Greyhound para Austin.`))}]};
}},

/* =============== C · Earl (4) =============== */
{id:'p2_earl4',when:()=>!!S.flags.ev_p2_earl3&&P2.at(47,3,2,0)(),run:()=>{const lost=S.flags.p2_saloon==='travis';
 return {title:t(`最后一轮`,`Last round`,`A última rodada`),meta:P2.M.earl,text:[
  lost?t(`明天施工队就进场。厄尔最后一次站在吧台后面，酒吧里挤满了人，谁都不说话，只有点唱机在响。`,`The work crew comes tomorrow. Earl stands behind the bar one last time; the place is packed, nobody talking, only the jukebox.`,`A equipa de obras chega amanhã. O Earl está atrás do balcão pela última vez; a casa está cheia, ninguém fala, só a jukebox.`)
   :t(`厄尔最后一次站在吧台后面。他把杯子一只一只擦干、挂好，然后走出来，坐到吧台尽头那张凳子上——客人的位置。`,`Earl works behind the bar one last time. He dries the glasses one by one, hangs them up, then comes round and sits on the stool at the end — the customer's side.`,`O Earl trabalha atrás do balcão pela última vez. Seca os copos um a um, pendura-os e depois dá a volta e senta-se no banco do fundo — do lado dos clientes.`),
  t(`“那头逃跑的公牛，”他突然说，“是真的。若泽追了它三条街，最后是它把若泽追回来的。”全场大笑。`,`"That runaway bull," he says out of nowhere. "It was true. José chased it three blocks, and then it chased José back." The whole room roars.`,`«Aquele touro fugido», diz de repente. «Era verdade. O José correu atrás dele três quarteirões, e depois foi o touro que correu atrás do José.» A sala inteira desata a rir.`),
  ({bought:t(`吧台后面现在站着你。厄尔看着你倒酒，嘴唇一动一动，在替你数杯子。`,`You're the one behind the bar now. Earl watches you pour, lips moving, counting the glasses for you.`,`Agora quem está atrás do balcão és tu. O Earl vê-te servir, a mexer os lábios, a contar os copos por ti.`),half:t(`乔琳站在吧台后面，你站在她旁边。厄尔说他这辈子没见过这么好看的两个酒保，也没见过这么慢的。`,`Jolene's behind the bar and you're beside her. Earl says he's never seen two prettier bartenders in his life, or two slower ones.`,`A Jolene está atrás do balcão e tu ao lado dela. O Earl diz que nunca viu dois empregados de bar tão bonitos, nem tão lentos.`),jolene:t(`乔琳站在吧台后面，头发扎起来的样子，和墙上那张她外婆的老照片一模一样。`,`Jolene's behind the bar, hair tied up exactly like her grandmother in the old photo on the wall.`,`A Jolene está atrás do balcão, o cabelo apanhado tal e qual a avó na fotografia antiga da parede.`),coop:t(`七十五个股东今晚全来了，每个人都觉得自己有权点歌。点唱机从来没这么忙过。`,`All seventy-five shareholders are here tonight, and every one of them thinks they get to pick a song. The jukebox has never been so busy.`,`Os setenta e cinco acionistas vieram todos esta noite, e cada um acha que tem direito a escolher uma canção. A jukebox nunca trabalhou tanto.`)}[S.flags.p2_saloon]||t(`门外停着施工队的卡车，车门上印着“孤星砂业”。没人朝那边看。`,`The work crew's truck is parked outside, LONE STAR SAND on the door. Nobody looks that way.`,`À porta está a carrinha da obra, com LONE STAR SAND na porta. Ninguém olha para lá.`))],choices:[
  {t:t(`[$150] 请他倒最后一轮，你买单`,`[$150] Ask him to pour the last round — on you`,`[$150] Pedir-lhe que sirva a última rodada — pagas tu`),req:MONEY(150),fx:()=>{S.cash-=150;S.rep+=2;addLike('earl',1)},next:()=>say(t(`一百多杯`,`A hundred glasses`,`Mais de cem copos`),t(`一百多杯。厄尔倒到最后一杯，手一点也没抖。`,`Over a hundred glasses. Earl pours to the very last, and his hand doesn't shake once.`,`Mais de cem copos. O Earl serve até ao último, e a mão não lhe treme nem uma vez.`))},
  {t:t(`请凯尔的乐队唱《孤星法多》`,`Ask Kyle's band for "Lone Star Fado"`,`Pedir à banda do Kyle o «Fado da Estrela Solitária»`),req:()=>rel('kyle').met||NEED(t(`认识凯尔`,`Know Kyle`,`Conhecer o Kyle`)),fx:()=>{addLike('kyle',1);stat('saud',2);addTrust('earl',1)},next:()=>say(t(`跑调`,`Off key`,`Desafinado`),t(`厄尔跟着哼，一路跑调跑到了里斯本。`,`Earl hums along, off key all the way to Lisbon.`,`O Earl trauteia, desafinado até Lisboa.`))},
  {t:t(`[手艺 40] 把若泽画的那颗星拓下来，裱给他`,`[Craft 40] Trace José's star from the sign and frame it for him`,`[Ofício 40] Decalcar a estrela do José e emoldurá-la para ele`),req:()=>S.stats.oficio>=40||NEED(t(`手艺 40`,`Craft 40`,`Ofício 40`)),fx:()=>{addTrust('earl',2);S.flags.p2_star=1},next:()=>say(t(`一面旗`,`A flag`,`Uma bandeira`),t(`他把画框夹在胳膊底下，像夹着一面旗。“我是开坦克的，不懂画。可我认得这颗星。”`,`He tucks the frame under his arm like a folded flag. "I drove tanks. Don't know nothing about pictures. But I know this star."`,`Mete o quadro debaixo do braço como uma bandeira dobrada. «Eu conduzia tanques. Não percebo nada de quadros. Mas conheço esta estrela.»`))},
  {t:t(`安静地陪他坐到打烊`,`Sit with him quietly till closing`,`Ficar com ele em silêncio até fechar`),fx:()=>{addTrust('earl',1);stat('saud',2)}}]};
}}
);
